export const PHYSICAL_SCIENCES_2_QUIZZES = [
  {
    id:'cp101', cat:'Physical Sciences', title:'SI Units & Scientific Notation', diff:'Easy',
    qs:[
      { q:`Which is the SI base unit of mass?`, ch:[`Kilogram`,`Pound`,`Ounce`,`Gram`], ans:0, exp:`The kilogram (kg) is the SI base unit of mass. The gram is a smaller, related unit but the kilogram is the official base unit. Pounds and ounces are non-SI (imperial) units.` },
      { q:`Which is the SI base unit of length?`, ch:[`Yard`,`Inch`,`Meter`,`Foot`], ans:2, exp:`The meter (m) is the SI base unit of length. Inches, feet, and yards are imperial units not used in the SI system.` },
      { q:`Which is the SI base unit of time?`, ch:[`Minute`,`Second`,`Hour`,`Day`], ans:1, exp:`The second (s) is the SI base unit of time. Minutes, hours, and days are all defined in terms of seconds but are not themselves base units.` },
      { q:`Which is the SI base unit of temperature used in scientific work?`, ch:[`Celsius`,`Fahrenheit`,`Kelvin`,`Rankine`], ans:2, exp:`Kelvin (K) is the SI base unit of temperature, with 0 K representing absolute zero. Celsius is a common related scale, but Kelvin is the true SI base unit used in gas law calculations and thermodynamics.` },
      { q:`Which is the SI base unit of electric current?`, ch:[`Ohm`,`Watt`,`Volt`,`Ampere`], ans:3, exp:`The ampere (A) is the SI base unit of electric current. Volts measure potential difference, watts measure power, and ohms measure resistance — all derived units, not base units.` },
      { q:`In the number 6.02 x 10^23, what does the exponent 23 represent?`, ch:[`The precision of the measurement`,`The base number itself`,`How many places to move the decimal point to write the number in full`,`The number of digits before the decimal point`], ans:2, exp:`The exponent tells you how many places (and in which direction) to move the decimal point. A positive exponent of 23 means moving the decimal 23 places to the right, producing a very large number.` },
      { q:`Express 0.000045 in proper scientific notation.`, ch:[`4.5 x 10^5`,`4.5 x 10^4`,`45 x 10^-6`,`4.5 x 10^-5`], ans:3, exp:`Moving the decimal point 5 places to the right (from 0.000045 to 4.5) requires a negative exponent since the original number is less than 1: 4.5 x 10^-5. The coefficient must be between 1 and 10.` },
      { q:`Express 3,200,000 in proper scientific notation.`, ch:[`3.2 x 10^5`,`32 x 10^5`,`3.2 x 10^-6`,`3.2 x 10^6`], ans:3, exp:`Moving the decimal point 6 places to the left (from 3,200,000 to 3.2) gives 3.2 x 10^6. The coefficient 32 x 10^5 is not proper scientific notation because 32 is not between 1 and 10.` },
      { q:`Which metric prefix represents 10^-3?`, ch:[`micro`,`milli`,`kilo`,`centi`], ans:1, exp:`Milli- means one-thousandth (10^-3), as in millimeter or milliliter. Kilo- means 10^3, micro- means 10^-6, and centi- means 10^-2.` },
      { q:`Which metric prefix represents 10^3?`, ch:[`milli`,`kilo`,`hecto`,`deca`], ans:1, exp:`Kilo- means one thousand times (10^3), as in kilometer or kilogram. Hecto- is 10^2, deca- is 10^1, and milli- is 10^-3.` },
      { q:`5 km equals how many meters?`, ch:[`50,000`,`500`,`0.5`,`5,000`], ans:3, exp:`Since 1 km = 1,000 m, 5 km = 5 x 1,000 = 5,000 m.` },
      { q:`When multiplying two numbers in scientific notation, (a x 10^m)(b x 10^n), what happens to the exponents?`, ch:[`They are divided`,`They are added together`,`They are subtracted`,`They are multiplied together`], ans:1, exp:`Multiplying powers of 10 adds their exponents: 10^m x 10^n = 10^(m+n). The coefficients a and b are multiplied separately.` },
      { q:`Which of the following is NOT an SI base unit?`, ch:[`Kilogram`,`Liter`,`Second`,`Meter`], ans:1, exp:`The liter is a derived (non-SI-base) unit of volume; the SI base unit of volume is technically expressed in cubic meters (m^3). Meter, kilogram, and second are all SI base units.` },
      { q:`The SI unit for the amount of substance is the:`, ch:[`atom`,`gram`,`mole`,`molecule`], ans:2, exp:`The mole (mol) is the SI base unit for amount of substance, representing Avogadro's number (about 6.022 x 10^23) of particles. Grams measure mass, not the count of particles.` },
    ]
  },
  {
    id:'cp102', cat:'Physical Sciences', title:'Dimensional Analysis & Unit Conversion', diff:'Medium',
    qs:[
      { q:`Dimensional analysis primarily uses which technique to convert between units?`, ch:[`Ignoring the units entirely`,`Multiplying by conversion factors that equal 1`,`Squaring the units`,`Adding conversion factors`], ans:1, exp:`Dimensional analysis works by multiplying a quantity by one or more conversion factors, each of which is a fraction equal to 1 (like 1000 m / 1 km), so the value doesn't change, only the units do.` },
      { q:`Convert 60 miles per hour to feet per second (1 mile = 5,280 ft). Approximately what is the result?`, ch:[`88 ft/s`,`44 ft/s`,`176 ft/s`,`8.8 ft/s`], ans:0, exp:`60 mi/hr x 5280 ft/mi x 1 hr/3600 s = 316,800/3,600 ≈ 88 ft/s.` },
      { q:`How many seconds are in 2.5 hours?`, ch:[`900`,`150`,`9,000`,`15,000`], ans:2, exp:`2.5 hr x 3,600 s/hr = 9,000 s.` },
      { q:`Convert 2.5 liters to milliliters.`, ch:[`25 mL`,`2,500 mL`,`250 mL`,`25,000 mL`], ans:1, exp:`Since 1 L = 1,000 mL, 2.5 L x 1,000 mL/L = 2,500 mL.` },
      { q:`A conversion factor such as (1,000 m / 1 km) is valid to use in dimensional analysis because:`, ch:[`It converts mass into length`,`It is equal to 1, since the numerator and denominator represent the same physical length`,`It only works for metric units`,`It changes the actual size of the quantity`], ans:1, exp:`Since 1,000 m and 1 km describe the exact same distance, the fraction 1,000 m/1 km equals 1. Multiplying any quantity by 1 doesn't change its actual value, only the units it's expressed in.` },
      { q:`What is the correct setup to convert 45 g to kilograms?`, ch:[`45 g / (1 kg / 1,000 g)`,`45 g x (1,000 g / 1 kg)`,`45 g x (1 kg / 1 g)`,`45 g x (1 kg / 1,000 g)`], ans:3, exp:`To cancel grams and end up with kilograms, grams must be in the denominator of the conversion factor: 45 g x (1 kg/1,000 g) = 0.045 kg.` },
      { q:`Density has units of:`, ch:[`kg/m`,`kg/m^3`,`kg*m^3`,`m^3/kg`], ans:1, exp:`Density is mass divided by volume, so its units are mass per unit volume, such as kg/m^3 or g/cm^3.` },
      { q:`If a car travels 120 km in 2 hours, its speed in meters per second is approximately:`, ch:[`6.7 m/s`,`60 m/s`,`33.3 m/s`,`16.7 m/s`], ans:3, exp:`120 km = 120,000 m, and 2 hours = 7,200 s. 120,000 m / 7,200 s ≈ 16.7 m/s.` },
      { q:`Which technique checks whether an equation's units are consistent on both sides?`, ch:[`Significant figures`,`Dimensional analysis`,`Scientific notation`,`Order of magnitude estimation`], ans:1, exp:`Dimensional analysis (unit analysis) verifies that the units on each side of an equation match, which is a useful way to catch errors in derived formulas.` },
      { q:`Convert 5 feet to inches (1 ft = 12 in).`, ch:[`60`,`5`,`600`,`17`], ans:0, exp:`5 ft x 12 in/ft = 60 in.` },
      { q:`Convert 98.6 degrees Fahrenheit to Celsius using C = (F - 32) x 5/9. Approximately what is the result?`, ch:[`66 C`,`98.6 C`,`21 C`,`37 C`], ans:3, exp:`(98.6 - 32) x 5/9 = 66.6 x 5/9 ≈ 37 C, which is normal human body temperature.` },
      { q:`When converting units, if the given unit appears in the denominator of the original quantity, the conversion factor should place that same unit:`, ch:[`nowhere in the factor`,`in the numerator, so it cancels`,`squared in the numerator`,`in the denominator again`], ans:1, exp:`To cancel a unit that's in the denominator of the original quantity, that unit must appear in the numerator of the conversion factor.` },
      { q:`One cubic meter equals how many liters?`, ch:[`1,000`,`100`,`10`,`10,000`], ans:0, exp:`1 m^3 = 1,000 L, since 1 L is defined as 1,000 cm^3 and 1 m^3 = 1,000,000 cm^3 = 1,000 L.` },
      { q:`The speed of light is about 3 x 10^8 m/s. What is this in kilometers per second?`, ch:[`3 x 10^8 km/s`,`3 x 10^5 km/s`,`3 x 10^11 km/s`,`3 x 10^2 km/s`], ans:1, exp:`Dividing by 1,000 (since 1 km = 1,000 m) shifts the exponent down by 3: 3 x 10^8 m/s = 3 x 10^5 km/s.` },
    ]
  },
  {
    id:'cp103', cat:'Physical Sciences', title:'Significant Figures & Measurement Precision', diff:'Easy',
    qs:[
      { q:`How many significant figures are in 0.00420?`, ch:[`3`,`6`,`5`,`2`], ans:0, exp:`Leading zeros are never significant, so the zeros before "420" don't count. The digits 4, 2, and the trailing zero after the decimal point are all significant, giving 3 sig figs.` },
      { q:`How many significant figures are in 1002?`, ch:[`3`,`2`,`1`,`4`], ans:3, exp:`All nonzero digits are significant, and zeros trapped between nonzero digits (captive zeros) are also significant. So 1, 0, 0, and 2 are all significant, giving 4 sig figs.` },
      { q:`How many significant figures are in 3400 (written with no decimal point)?`, ch:[`2`,`4`,`3`,`5`], ans:0, exp:`By convention, trailing zeros in a number with no decimal point are considered not significant (they may just be placeholders). Only the 3 and 4 are significant, giving 2 sig figs.` },
      { q:`When adding or subtracting measurements, the result should be rounded to match:`, ch:[`always 2 decimal places`,`the least number of sig figs among the values`,`the most decimal places of any value`,`the fewest decimal places of any value being added`], ans:3, exp:`For addition and subtraction, the answer is limited by the value with the fewest decimal places, not by total sig figs.` },
      { q:`When multiplying or dividing measurements, the result should have:`, ch:[`the most sig figs of any value used`,`one more sig fig than the smallest value`,`the least number of sig figs of any value used`,`the same number of decimal places as the least precise value`], ans:2, exp:`For multiplication and division, the result is limited by the value with the fewest total significant figures.` },
      { q:`12.11 + 18.0 + 1.013 = ? What should the properly rounded answer be?`, ch:[`31.1`,`31`,`31.12`,`31.123`], ans:0, exp:`The raw sum is 31.123. Since 18.0 has only one decimal place (the fewest among the three values), the final answer must be rounded to one decimal place: 31.1.` },
      { q:`Which measurement shows the greatest precision (most significant figures)?`, ch:[`12 mL`,`12.00 mL`,`12.000 mL`,`12.0 mL`], ans:2, exp:`12.000 mL has 5 significant figures, more than any of the other options, indicating it was measured with the greatest precision.` },
      { q:`Zeros trapped between two nonzero digits (captive zeros), such as in 405, are:`, ch:[`never significant`,`ambiguous`,`significant only in decimals`,`always significant`], ans:3, exp:`Captive zeros between nonzero digits are always counted as significant figures.` },
      { q:`Leading zeros in a number like 0.0067 are:`, ch:[`never significant`,`significant only in whole numbers`,`always significant`,`significant only if before the decimal point`], ans:0, exp:`Leading zeros only serve to locate the decimal point and are never counted as significant figures. Only 6 and 7 are significant in 0.0067.` },
      { q:`Trailing zeros after a decimal point, such as in 5.20, are:`, ch:[`always significant`,`ambiguous`,`not significant`,`significant only if measured with a ruler`], ans:0, exp:`Trailing zeros that appear after a decimal point are always significant because they indicate the precision of the measurement.` },
      { q:`Exact numbers, such as counting 12 eggs or a defined conversion factor like 1 ft = 12 in, have:`, ch:[`infinite significant figures (they never limit precision)`,`zero significant figures`,`ambiguous significant figures`,`a limited number of sig figs`], ans:0, exp:`Exact numbers are treated as having infinitely many significant figures since they are not measurements, and so they never limit the precision of a calculated result.` },
      { q:`Round 6.398 to 2 significant figures.`, ch:[`6.40`,`6.3`,`6.0`,`6.4`], ans:3, exp:`Keeping only 2 sig figs means keeping the 6 and rounding based on the next digit (3, which rounds down), giving 6.4.` },
      { q:`A measuring tool with finer, smaller gradations (markings) generally allows for:`, ch:[`readings that don't depend on the tool at all`,`less precise readings`,`the same precision as any other tool`,`more precise readings, with more reliable significant figures`], ans:3, exp:`Instruments with finer gradations let you estimate one digit further, increasing the precision (and number of significant figures) of a reading.` },
      { q:`How many significant figures are in 500. (written with a decimal point shown after the last zero)?`, ch:[`2`,`3`,`It is ambiguous`,`1`], ans:1, exp:`Writing a decimal point after trailing zeros (500.) explicitly signals that those zeros are significant, giving 3 sig figs. Without the decimal point, it would be ambiguous.` },
    ]
  },
  {
    id:'cp104', cat:'Physical Sciences', title:'Density & Physical Properties of Matter', diff:'Easy',
    qs:[
      { q:`Density is defined as:`, ch:[`volume divided by mass`,`weight divided by area`,`mass times volume`,`mass divided by volume`], ans:3, exp:`Density = mass/volume. It describes how much matter is packed into a given amount of space.` },
      { q:`An object with a density less than water (1 g/mL) placed in water will generally:`, ch:[`dissolve completely`,`float`,`always remain exactly at the surface, fully submerged`,`sink`], ans:1, exp:`Objects less dense than the fluid they're placed in will float, with the buoyant force supporting their weight.` },
      { q:`A metal block has a mass of 54 g and a volume of 20 cm^3. What is its density?`, ch:[`34 g/cm^3`,`1,080 g/cm^3`,`0.37 g/cm^3`,`2.7 g/cm^3`], ans:3, exp:`Density = mass/volume = 54 g / 20 cm^3 = 2.7 g/cm^3.` },
      { q:`Which physical property describes a fluid's resistance to flow?`, ch:[`Malleability`,`Viscosity`,`Conductivity`,`Density`], ans:1, exp:`Viscosity measures how resistant a fluid is to flowing; honey has a much higher viscosity than water.` },
      { q:`Malleability describes a material's ability to:`, ch:[`resist changes in temperature`,`conduct electricity`,`be hammered or rolled into thin sheets without breaking`,`dissolve readily in water`], ans:2, exp:`Malleability is the property that allows metals like gold and copper to be shaped into thin sheets without cracking.` },
      { q:`Which of these is a physical property (not a chemical property)?`, ch:[`Melting point`,`Reactivity with acid`,`Flammability`,`Tendency to rust`], ans:0, exp:`Melting point can be observed without changing the substance into a new substance, making it a physical property. Flammability, acid reactivity, and rusting all involve chemical changes.` },
      { q:`Which of these is a chemical property?`, ch:[`Density`,`Color`,`Ability to rust (react with oxygen)`,`Melting point`], ans:2, exp:`Rusting involves a chemical reaction that transforms iron into a new substance (iron oxide), so it's a chemical property. Color, density, and melting point are physical properties.` },
      { q:`Two liquids, like oil and water, that do not mix together are described as:`, ch:[`soluble`,`miscible`,`immiscible`,`homogeneous`], ans:2, exp:`Immiscible liquids don't dissolve into one another and instead form separate layers, unlike miscible liquids which mix completely.` },
      { q:`As temperature increases, the density of most liquids:`, ch:[`stays exactly the same`,`becomes negative`,`decreases`,`increases`], ans:2, exp:`Heating a liquid generally causes it to expand (increase in volume) while its mass stays constant, so its density decreases.` },
      { q:`Water is unusual because its solid form, ice, is:`, ch:[`exactly the same density as liquid water`,`unrelated to density in any way`,`less dense than liquid water`,`denser than liquid water`], ans:2, exp:`Ice is less dense than liquid water due to the open hexagonal structure formed by hydrogen bonding when water freezes, which is why ice floats.` },
      { q:`A substance's mass per unit volume, often used to help identify materials, is called its:`, ch:[`pressure`,`buoyancy`,`weight`,`density`], ans:3, exp:`Density is an intensive property (independent of sample size) that is useful for identifying substances, since each material has a characteristic density.` },
      { q:`If object A has greater density than object B, and both objects have the same volume, object A must have:`, ch:[`more mass than object B`,`no measurable mass`,`the same mass as object B`,`less mass than object B`], ans:0, exp:`Since density = mass/volume, at equal volumes a higher density means a greater mass.` },
      { q:`Specific gravity is the ratio of a substance's density to the density of:`, ch:[`mercury`,`air`,`gold`,`water`], ans:3, exp:`Specific gravity compares a substance's density to that of water (1 g/mL or 1,000 kg/m^3) at a reference temperature, giving a dimensionless value.` },
      { q:`Which unit is commonly used to express density?`, ch:[`N*m`,`J/kg`,`g/cm^3`,`m/s`], ans:2, exp:`Density is commonly expressed in grams per cubic centimeter (g/cm^3) or kilograms per cubic meter (kg/m^3).` },
    ]
  },
  {
    id:'cp105', cat:'Physical Sciences', title:'Types of Chemical Reactions', diff:'Easy',
    qs:[
      { q:`A + B -> AB is the general pattern for which reaction type?`, ch:[`Single replacement`,`Synthesis (combination)`,`Decomposition`,`Double replacement`], ans:1, exp:`In a synthesis (combination) reaction, two or more simple substances combine to form one more complex product.` },
      { q:`AB -> A + B is the general pattern for which reaction type?`, ch:[`Combustion`,`Double replacement`,`Decomposition`,`Synthesis`], ans:2, exp:`A decomposition reaction breaks a single compound down into two or more simpler substances.` },
      { q:`A + BC -> AC + B is the general pattern for which reaction type?`, ch:[`Synthesis`,`Double replacement`,`Decomposition`,`Single replacement (displacement)`], ans:3, exp:`In a single replacement reaction, one element displaces another element from a compound.` },
      { q:`AB + CD -> AD + CB is the general pattern for which reaction type?`, ch:[`Double replacement (metathesis)`,`Combustion`,`Single replacement`,`Synthesis`], ans:0, exp:`In a double replacement reaction, the cations (or anions) of two compounds essentially trade partners.` },
      { q:`A hydrocarbon reacting with oxygen to produce carbon dioxide and water is called a:`, ch:[`Neutralization reaction`,`Combustion reaction`,`Precipitation reaction`,`Decomposition reaction`], ans:1, exp:`Combustion reactions involve a fuel (often a hydrocarbon) reacting rapidly with oxygen, releasing energy and producing CO2 and H2O.` },
      { q:`Which best classifies the reaction 2H2 + O2 -> 2H2O?`, ch:[`Decomposition`,`Double replacement`,`Synthesis (combination)`,`Single replacement`], ans:2, exp:`Two simple substances (hydrogen and oxygen) combine into one compound (water), which is the definition of a synthesis reaction.` },
      { q:`An acid reacting with a base to produce water and a salt is called:`, ch:[`Neutralization`,`Combustion`,`Synthesis`,`Decomposition`], ans:0, exp:`Neutralization reactions occur when an acid and base react, typically producing water and an ionic salt.` },
      { q:`When two aqueous ionic solutions react and form an insoluble solid, the reaction is a:`, ch:[`Combustion reaction`,`Synthesis reaction`,`Precipitation reaction`,`Decomposition reaction`], ans:2, exp:`A precipitation reaction occurs when the combination of two soluble ionic compounds produces an insoluble solid (precipitate) that falls out of solution.` },
      { q:`The law of conservation of mass states that:`, ch:[`mass is neither created nor destroyed in a chemical reaction`,`mass always increases during a reaction`,`mass is only conserved in physical changes, not chemical ones`,`mass can be created during a chemical reaction`], ans:0, exp:`In any closed chemical reaction, the total mass of the reactants equals the total mass of the products; atoms are only rearranged, not created or destroyed.` },
      { q:`In the unbalanced equation CH4 + O2 -> CO2 + H2O, balancing the equation ensures that:`, ch:[`only carbon atoms are balanced`,`the number of atoms of each element is equal on both sides`,`the number of molecules is equal on both sides`,`the reaction becomes exothermic`], ans:1, exp:`Balancing adjusts coefficients so that the same number of atoms of each element appears on the reactant and product sides, consistent with conservation of mass.` },
      { q:`Which of the following is an example of a single replacement reaction?`, ch:[`NaCl + AgNO3 -> AgCl + NaNO3`,`Zn + 2HCl -> ZnCl2 + H2`,`CaO + CO2 -> CaCO3`,`2H2O -> 2H2 + O2`], ans:1, exp:`In Zn + 2HCl -> ZnCl2 + H2, the zinc metal displaces hydrogen from hydrochloric acid, which is characteristic of a single replacement reaction.` },
      { q:`Rusting of iron, 4Fe + 3O2 -> 2Fe2O3, is best classified as a:`, ch:[`Synthesis (combination) reaction`,`Neutralization reaction`,`Decomposition reaction`,`Double replacement reaction`], ans:0, exp:`Iron metal and oxygen gas combine to form one compound (iron oxide), which is the hallmark of a synthesis reaction.` },
      { q:`When silver nitrate solution is mixed with sodium chloride solution, a white solid of silver chloride forms. This is an example of a:`, ch:[`Double replacement (precipitation) reaction`,`Single replacement reaction`,`Combustion reaction`,`Synthesis reaction`], ans:0, exp:`The silver and sodium ions swap partners, and the newly formed silver chloride is insoluble, precipitating out of solution — a double replacement/precipitation reaction.` },
      { q:`Which statement about balanced chemical equations is true?`, ch:[`Mass is not conserved once an equation is balanced`,`Coefficients are adjusted in front of formulas to conserve atoms`,`Coefficients may only be fractions`,`Subscripts may be changed freely to balance the equation`], ans:1, exp:`Balancing is done by changing coefficients (whole-number multipliers in front of formulas), never subscripts, since changing subscripts would change the identity of the substance.` },
    ]
  },
  {
    id:'cp106', cat:'Physical Sciences', title:'Precipitation Reactions & Solubility Rules', diff:'Medium',
    qs:[
      { q:`A precipitate forms in solution when:`, ch:[`two soluble reactants combine to form another soluble product`,`two soluble reactants combine to form an insoluble solid product`,`water simply evaporates`,`a gas bubbles out of solution`], ans:1, exp:`A precipitate is an insoluble solid that forms when ions from two soluble compounds combine into a compound that does not dissolve well in water.` },
      { q:`According to common solubility rules, salts containing which ion are almost always soluble?`, ch:[`Nitrate (NO3-)`,`Sulfide (S^2-)`,`Phosphate (PO4^3-)`,`Carbonate (CO3^2-)`], ans:0, exp:`Nearly all nitrate salts are soluble in water, which makes nitrate compounds like AgNO3 or Ca(NO3)2 useful sources of their cations in solution.` },
      { q:`Which compound below is generally insoluble in water?`, ch:[`AgCl`,`NH4Br`,`KNO3`,`NaCl`], ans:0, exp:`Silver chloride (AgCl) is one of the classic exceptions to the general rule that halide salts are soluble; it is insoluble and forms a white precipitate.` },
      { q:`Most sulfate (SO4^2-) salts are soluble EXCEPT those of:`, ch:[`Ba, Pb, and Ca (partially)`,`Cl and Br`,`Mg and Al`,`Na, K, and NH4`], ans:0, exp:`Barium sulfate and lead(II) sulfate are classic insoluble exceptions to the general solubility of sulfates; calcium sulfate is only slightly soluble.` },
      { q:`In the overall (molecular) equation for a precipitation reaction, spectator ions are:`, ch:[`always cations only`,`only ever found in gases`,`the ions that combine to form the precipitate`,`ions that appear unchanged on both sides of the equation and are left out of the net ionic equation`], ans:3, exp:`Spectator ions remain dissolved and unreacted throughout the process, so they are omitted when writing the net ionic equation, which shows only the ions that actually form the precipitate.` },
      { q:`What is the net ionic equation for AgNO3(aq) + NaCl(aq) -> AgCl(s) + NaNO3(aq)?`, ch:[`Na+ + NO3- -> NaNO3(s)`,`Ag+ + NO3- -> AgNO3(aq)`,`Na+ + Cl- -> NaCl(s)`,`Ag+ + Cl- -> AgCl(s)`], ans:3, exp:`Only the silver and chloride ions actually combine to form the solid precipitate; sodium and nitrate remain dissolved as spectator ions and are excluded from the net ionic equation.` },
      { q:`Alkali metal (Group 1) compounds are generally:`, ch:[`insoluble as halides`,`insoluble in water`,`soluble in nearly all cases`,`soluble only as sulfates`], ans:2, exp:`Salts of Group 1 (alkali metal) cations, such as Na+ and K+, are essentially always soluble in water, regardless of the anion.` },
      { q:`Which pair of solutions, when mixed, would you predict to form a precipitate?`, ch:[`BaCl2(aq) + Na2SO4(aq)`,`NH4Cl(aq) + KBr(aq)`,`NaCl(aq) + KNO3(aq)`,`KOH(aq) + NaNO3(aq)`], ans:0, exp:`Mixing BaCl2 and Na2SO4 would produce insoluble barium sulfate (BaSO4) as a precipitate, since Ba2+ and SO4^2- form one of the classic insoluble sulfate exceptions.` },
      { q:`Most carbonate (CO3^2-) salts are:`, ch:[`soluble only in strong acids`,`soluble`,`always gases at room temperature`,`insoluble, except those of Group 1 cations and ammonium`], ans:3, exp:`Carbonates are generally insoluble, with the notable exceptions of Group 1 metal carbonates and ammonium carbonate, which are soluble.` },
      { q:`A double replacement reaction that produces a precipitate is driven forward because:`, ch:[`the reaction is always strongly exothermic`,`removal of ions from solution as an insoluble solid pulls the reaction toward completion`,`the products are always more soluble than the reactants`,`a gas is always released`], ans:1, exp:`As ions leave the solution to form an insoluble solid, their concentration in solution drops, which favors the forward reaction (an application of Le Chatelier's principle).` },
      { q:`Which halide ion, when paired with silver, is an exception and forms a soluble compound?`, ch:[`F-`,`I-`,`Br-`,`Cl-`], ans:0, exp:`Silver fluoride (AgF) is soluble, unlike silver chloride, bromide, and iodide, which are all insoluble.` },
      { q:`When writing a complete ionic equation, strong electrolytes (soluble ionic compounds) dissolved in water are written as:`, ch:[`separated, dissociated ions`,`gases`,`molecular solids`,`undissociated formula units`], ans:0, exp:`Strong electrolytes fully dissociate in water, so in a complete ionic equation they are written as their separate cation and anion in aqueous form.` },
      { q:`Lead(II) sulfate (PbSO4) is:`, ch:[`only found dissolved in strong acids`,`highly soluble in water`,`insoluble, an exception among sulfate salts`,`a gas at room temperature`], ans:2, exp:`Along with barium sulfate, lead(II) sulfate is a well-known exception to the general solubility of sulfate salts and forms a precipitate.` },
      { q:`If mixing two solutions produces no precipitate, no gas, and no water, the reaction is best described as:`, ch:[`a neutralization reaction`,`a combustion reaction`,`a precipitation reaction`,`essentially having no net reaction, with all ions remaining as spectators`], ans:3, exp:`If none of the possible products are insoluble, gaseous, or molecular (like water), the ions simply remain dissolved and no net chemical change occurs.` },
    ]
  },
  {
    id:'cp107', cat:'Physical Sciences', title:'Oxidation Numbers & Basic Redox Reactions', diff:'Medium',
    qs:[
      { q:`Oxidation is defined as:`, ch:[`a loss of electrons`,`a loss of protons`,`a gain of electrons`,`a gain of protons`], ans:0, exp:`Oxidation is the loss of electrons by an atom, ion, or molecule, which typically increases its oxidation number.` },
      { q:`Reduction is defined as:`, ch:[`a loss of electrons`,`a loss of protons`,`a gain of electrons`,`a gain of neutrons`], ans:2, exp:`Reduction is the gain of electrons by a species, which typically decreases its oxidation number.` },
      { q:`The oxidation number of an atom in its pure elemental form, like O2 gas or solid Fe metal, is:`, ch:[`+2`,`+1`,`-1`,`0`], ans:3, exp:`Atoms in their elemental, uncombined state always have an oxidation number of zero.` },
      { q:`In most compounds, the oxidation number of oxygen is:`, ch:[`+2`,`-1`,`-2`,`0`], ans:2, exp:`Oxygen almost always has an oxidation number of -2 in compounds (peroxides like H2O2 are an exception, where it is -1).` },
      { q:`In most compounds, the oxidation number of hydrogen is:`, ch:[`+1`,`0`,`+2`,`-1`], ans:0, exp:`Hydrogen typically has an oxidation number of +1 when bonded to nonmetals (it is -1 only when bonded to a metal, as in metal hydrides).` },
      { q:`The sum of all oxidation numbers in a neutral compound must equal:`, ch:[`-1`,`+1`,`0`,`the number of atoms in the formula`], ans:2, exp:`Because the overall compound is electrically neutral, the oxidation numbers of all atoms must sum to zero.` },
      { q:`In the reaction Zn + Cu2+ -> Zn2+ + Cu, zinc is:`, ch:[`oxidized`,`reduced`,`acting as a spectator`,`neither oxidized nor reduced`], ans:0, exp:`Zinc goes from an oxidation state of 0 to +2, losing two electrons, so it is oxidized.` },
      { q:`In the same reaction, Zn + Cu2+ -> Zn2+ + Cu, the Cu2+ ion is:`, ch:[`unchanged`,`reduced`,`oxidized`,`acting as a catalyst`], ans:1, exp:`Copper(II) ion gains two electrons to become neutral copper metal, going from +2 to 0, which is a reduction.` },
      { q:`A reducing agent is a substance that:`, ch:[`never loses or gains electrons`,`gets reduced by losing electrons`,`is always a metal cation`,`causes another substance to be reduced by being oxidized itself`], ans:3, exp:`A reducing agent donates electrons to another species (causing that species to be reduced), and in doing so it is itself oxidized.` },
      { q:`An oxidizing agent is a substance that:`, ch:[`is itself reduced, causing another substance to be oxidized`,`never reacts with anything`,`is always a nonmetal anion`,`is itself oxidized`], ans:0, exp:`An oxidizing agent accepts electrons from another species (causing that species to be oxidized), and in the process it is itself reduced.` },
      { q:`What is the oxidation number of sulfur in the sulfate ion, SO4^2-?`, ch:[`+4`,`-2`,`+6`,`+2`], ans:2, exp:`Each oxygen contributes -2, totaling -8 for four oxygens. Since the overall ion charge is -2, sulfur must be +6 (S + (-8) = -2, so S = +6).` },
      { q:`What is the oxidation number of chromium in the dichromate ion, Cr2O7^2-?`, ch:[`+3`,`+6`,`+7`,`+2`], ans:1, exp:`Seven oxygens contribute -14 total. With an overall charge of -2, the two chromium atoms together must total +12 (2Cr - 14 = -2), so each chromium is +6.` },
      { q:`The mnemonic "OIL RIG" is used to remember that:`, ch:[`Oxygen Is Lost, Reduction Involves Gases`,`Oxidation Is Loss (of electrons), Reduction Is Gain (of electrons)`,`Oxidation Is Gain, Reduction Is Loss`,`Oxidation Involves Ligands, Reduction Ions Gain`], ans:1, exp:`OIL RIG stands for "Oxidation Is Loss, Reduction Is Gain" of electrons, a handy way to remember the electron-transfer definitions.` },
      { q:`In any redox reaction, the total number of electrons lost by the species oxidized must:`, ch:[`always be zero`,`be exactly twice the electrons gained`,`equal the number of protons involved in the reaction`,`equal the number of electrons gained by the species reduced`], ans:3, exp:`Electrons are conserved: every electron lost by the oxidized species must be gained by the reduced species, so the totals must be equal.` },
    ]
  },
  {
    id:'cp108', cat:'Physical Sciences', title:'Galvanic Cells & Batteries Basics', diff:'Medium',
    qs:[
      { q:`In a galvanic (voltaic) cell, oxidation occurs at the:`, ch:[`salt bridge`,`anode`,`cathode`,`external wire`], ans:1, exp:`By definition, oxidation always occurs at the anode in any electrochemical cell.` },
      { q:`Reduction in a galvanic cell occurs at the:`, ch:[`salt bridge`,`none of these locations`,`cathode`,`anode`], ans:2, exp:`By definition, reduction always occurs at the cathode.` },
      { q:`In a galvanic cell, electrons flow through the external wire from the:`, ch:[`salt bridge to the anode`,`cathode to the anode`,`cathode to the salt bridge`,`anode to the cathode`], ans:3, exp:`Electrons are released during oxidation at the anode and travel through the external circuit to the cathode, where they are consumed in the reduction reaction.` },
      { q:`The purpose of a salt bridge in a galvanic cell is to:`, ch:[`generate voltage on its own`,`conduct electrons directly between the two half-cells`,`maintain electrical neutrality by allowing ion flow between half-cells`,`act as one of the electrodes`], ans:2, exp:`As electrons flow through the wire, charge would build up in each half-cell without the salt bridge; it allows ions to migrate and keep both solutions electrically neutral.` },
      { q:`A galvanic cell converts:`, ch:[`chemical energy into electrical energy`,`electrical energy into chemical energy`,`light energy into chemical energy`,`mechanical energy into heat`], ans:0, exp:`Galvanic cells harness a spontaneous redox reaction to generate an electric current, converting chemical potential energy into electrical energy.` },
      { q:`In battery terminology, the negative terminal of a battery corresponds to the:`, ch:[`anode`,`salt bridge`,`cathode`,`separator`], ans:0, exp:`In a discharging (galvanic) battery, the anode is the site of oxidation and electron release, making it the negative terminal.` },
      { q:`A half-cell with a more positive standard reduction potential compared to another half-cell will act as the:`, ch:[`neither electrode`,`cathode (site of reduction)`,`salt bridge`,`anode (site of oxidation)`], ans:1, exp:`The half-reaction with the higher (more positive) reduction potential is more likely to be reduced, so it becomes the cathode, while the other half-cell becomes the anode.` },
      { q:`An electrolytic cell differs from a galvanic cell in that it:`, ch:[`produces electricity spontaneously`,`requires an external power source to drive a non-spontaneous reaction`,`can never be recharged`,`has no anode or cathode`], ans:1, exp:`Electrolytic cells use an external voltage source to force a non-spontaneous redox reaction to occur, unlike galvanic cells, which generate current from a spontaneous reaction.` },
      { q:`In a simple zinc-copper cell, given that zinc is more reactive than copper, which metal is oxidized?`, ch:[`Zinc`,`Copper`,`Neither metal`,`Both equally`], ans:0, exp:`Zinc is more easily oxidized than copper, so it loses electrons and dissolves into solution as Zn2+, acting as the anode.` },
      { q:`A "dead" battery has reached a point where:`, ch:[`the cell reaction has essentially reached equilibrium, with little net electron flow remaining`,`the salt bridge has dissolved`,`electrons are flowing faster than ever`,`the anode has been fully reduced`], ans:0, exp:`As the reactants are used up, the driving force for the reaction diminishes until the cell reaches equilibrium and can no longer produce useful current.` },
      { q:`The standard cell potential (E cell) for a spontaneous galvanic reaction is:`, ch:[`zero`,`positive`,`undefined`,`negative`], ans:1, exp:`A positive standard cell potential indicates a spontaneous reaction under standard conditions, which is required for a galvanic cell to generate current.` },
      { q:`Rechargeable batteries can have their electrode reactions reversed by:`, ch:[`removing the salt bridge`,`heating the battery to a high temperature`,`adding more electrolyte solution`,`applying an external voltage, running the cell in electrolytic mode`], ans:3, exp:`Recharging a battery means applying an external power source to force the reverse (non-spontaneous) reaction, restoring the original reactants.` },
      { q:`In the cell notation Zn(s) | Zn2+(aq) || Cu2+(aq) | Cu(s), the double vertical line represents the:`, ch:[`salt bridge`,`external wire`,`voltmeter`,`anode surface`], ans:0, exp:`The double line in standard cell notation represents the salt bridge (or porous barrier) separating the two half-cells.` },
      { q:`Corrosion of metal, such as iron rusting, is essentially:`, ch:[`an unwanted, spontaneous redox (electrochemical) reaction`,`a nuclear process`,`a purely physical process with no electron transfer`,`a reaction that requires an external power source`], ans:0, exp:`Rusting involves iron being oxidized by oxygen (often with water present), which is a spontaneous electrochemical process, just like in a galvanic cell.` },
    ]
  },
  {
    id:'cp109', cat:'Physical Sciences', title:'Simple Machines & Mechanical Advantage', diff:'Easy',
    qs:[
      { q:`Mechanical advantage is defined as the ratio of:`, ch:[`output distance to time`,`input distance to output distance`,`input force to time`,`output force to input force`], ans:3, exp:`Mechanical advantage = output force / input force, describing how much a machine multiplies the applied force.` },
      { q:`Levers, pulleys, wheel and axles, inclined planes, wedges, and screws are all examples of:`, ch:[`hydraulic systems`,`complex machines`,`electrical devices`,`simple machines`], ans:3, exp:`These six devices are classified as the basic simple machines, each of which changes the size or direction of an applied force.` },
      { q:`In a first-class lever, the fulcrum is located:`, ch:[`there is no fulcrum in a first-class lever`,`only at the load end`,`between the effort and the load`,`only at the effort end`], ans:2, exp:`A first-class lever has the fulcrum positioned between the effort and the load, like a seesaw.` },
      { q:`A seesaw is a classic example of which class of lever?`, ch:[`First class`,`Not a lever`,`Second class`,`Third class`], ans:0, exp:`A seesaw has its fulcrum (pivot) in the middle, between the two riders, making it a first-class lever.` },
      { q:`A wheelbarrow is a classic example of which class of lever?`, ch:[`Not a lever`,`First class`,`Second class`,`Third class`], ans:2, exp:`A wheelbarrow has its load between the fulcrum (the wheel) and the effort (your hands), making it a second-class lever.` },
      { q:`In a second-class lever, the load is located:`, ch:[`there is no load in a second-class lever`,`exactly at the fulcrum`,`beyond the effort, farthest from the fulcrum`,`between the fulcrum and the effort`], ans:3, exp:`Second-class levers place the load between the fulcrum and the point where effort is applied, giving a mechanical advantage greater than 1.` },
      { q:`An inclined plane makes lifting a heavy object easier by:`, ch:[`decreasing the force needed while increasing the distance over which it is applied`,`increasing both the force and distance needed`,`increasing the force needed but decreasing the distance moved`,`eliminating the need for any force`], ans:0, exp:`A ramp trades distance for force: you push with less force, but over a longer distance, to raise an object to the same height.` },
      { q:`The mechanical advantage of an inclined plane is calculated as:`, ch:[`the length of the incline divided by its height`,`the height divided by the length`,`the length times the height`,`the force divided by the height`], ans:0, exp:`Ideal mechanical advantage of a ramp = length of incline / height of incline; a longer, gentler ramp gives a greater mechanical advantage.` },
      { q:`A single fixed pulley (attached to a stationary point) mainly changes the:`, ch:[`magnitude of the force needed to lift a load`,`total amount of work done`,`mass of the object being lifted`,`direction of the applied force, without providing a mechanical advantage`], ans:3, exp:`A single fixed pulley lets you pull down to lift something up, changing the direction of your effort, but its ideal mechanical advantage is 1 (it doesn't reduce the force needed).` },
      { q:`A movable pulley system with a mechanical advantage of 2 means:`, ch:[`no force is needed to lift the load`,`the load moves twice as fast as the rope is pulled`,`you can apply half the force needed to lift the load directly`,`you must apply twice the force needed to lift the load directly`], ans:2, exp:`A mechanical advantage of 2 means the effort force required is half of the load's weight, though you must pull the rope twice the distance the load rises.` },
      { q:`A wedge is essentially two inclined planes joined together to:`, ch:[`increase the object's weight`,`reduce friction to zero`,`split or cut material by concentrating an applied force`,`function like a pulley`], ans:2, exp:`Wedges, like axe heads or knife blades, concentrate force into a small area, allowing them to split or cut through materials.` },
      { q:`The mechanical advantage of a wheel and axle is the ratio of:`, ch:[`the radius of the wheel to the radius of the axle`,`the radius of the axle to the radius of the wheel`,`the rotational speed of the wheel to the axle`,`the mass of the wheel to the mass of the axle`], ans:0, exp:`Turning the larger wheel through a greater distance with less force rotates the smaller axle with more force, giving a mechanical advantage equal to wheel radius / axle radius.` },
      { q:`A screw can be thought of as:`, ch:[`an inclined plane wrapped around a cylinder`,`a wheel with no axle`,`a lever wrapped around a wedge`,`a type of pulley system`], ans:0, exp:`A screw's threads form a continuous inclined plane wound around a cylindrical shaft, allowing rotational force to be converted into a strong linear force.` },
      { q:`Ideal mechanical advantage calculations typically assume:`, ch:[`significant friction losses`,`that the machine does no work at all`,`that the load never moves`,`no friction losses (100% efficiency)`], ans:3, exp:`Ideal mechanical advantage is a theoretical value that ignores friction; real (actual) mechanical advantage is always somewhat lower due to friction losses.` },
      { q:`A lever has an effort arm of 4 m and a load arm of 1 m. What is its ideal mechanical advantage?`, ch:[`1`,`5`,`4`,`0.25`], ans:2, exp:`Ideal mechanical advantage of a lever = effort arm length / load arm length = 4 m / 1 m = 4.` },
    ]
  },
  {
    id:'cp110', cat:'Physical Sciences', title:'Circular Motion Basics', diff:'Easy',
    qs:[
      { q:`An object moving in a circle at constant speed experiences:`, ch:[`zero acceleration`,`centripetal acceleration directed toward the center`,`acceleration directed away from the center`,`constant velocity (unchanging direction)`], ans:1, exp:`Even at constant speed, the direction of velocity is constantly changing in circular motion, producing a centripetal acceleration that always points toward the center.` },
      { q:`Centripetal force always points:`, ch:[`in the same direction as the velocity`,`away from the center`,`tangent to the circular path`,`toward the center of the circle`], ans:3, exp:`"Centripetal" means "center-seeking" — this net force always points toward the center of the circular path, keeping the object turning.` },
      { q:`Which formula correctly gives centripetal acceleration?`, ch:[`a = r/v^2`,`a = v*r^2`,`a = v^2/r`,`a = v/r`], ans:2, exp:`Centripetal acceleration is calculated as a = v^2/r, where v is speed and r is the radius of the circular path.` },
      { q:`If the speed of an object in circular motion doubles while the radius stays the same, the centripetal force required:`, ch:[`is cut in half`,`quadruples`,`stays the same`,`doubles`], ans:1, exp:`Since centripetal force depends on v^2, doubling the speed increases the required force by a factor of 2^2 = 4.` },
      { q:`Centripetal force is best described as:`, ch:[`always specifically gravity`,`a brand-new fundamental force of nature`,`the net force that causes and maintains circular motion`,`always specifically friction`], ans:2, exp:`Centripetal force isn't a distinct fundamental force — it's simply the name given to whatever net force (gravity, tension, friction, normal force, etc.) causes circular motion.` },
      { q:`A car turning on a flat, level curve relies mainly on which force to supply the centripetal force?`, ch:[`Friction between the tires and the road`,`Air resistance`,`Gravity`,`Normal force`], ans:0, exp:`On a flat curve, friction between the tires and road surface provides the centripetal force needed to keep the car turning instead of sliding straight.` },
      { q:`If the string holding a ball swinging in a horizontal circle suddenly breaks, the ball will:`, ch:[`continue moving in a circle`,`move directly toward the center`,`fall straight downward immediately`,`fly off in a straight line, tangent to the circle at the point it was released`], ans:3, exp:`Once the centripetal force (tension) is removed, there is no longer a net force curving the path, so by Newton's first law the ball travels in a straight line tangent to its circular path.` },
      { q:`The period (T) of circular motion is:`, ch:[`the speed at any point on the circle`,`the radius of the circular path`,`the time required for one full revolution`,`the distance traveled in one second`], ans:2, exp:`Period is the time it takes for an object to complete one full trip around the circle.` },
      { q:`Frequency of circular motion is related to the period by:`, ch:[`f = T^2`,`f = 1/T`,`f = 2T`,`f = T`], ans:1, exp:`Frequency (revolutions per second) is the reciprocal of the period (seconds per revolution): f = 1/T.` },
      { q:`Increasing the radius of a circular path while keeping the object's speed constant will:`, ch:[`have no effect on the required force`,`increase the required centripetal force`,`reverse the direction of motion`,`decrease the required centripetal force`], ans:3, exp:`Since centripetal force is inversely proportional to radius (F = mv^2/r), increasing the radius at constant speed decreases the required force.` },
      { q:`On a banked curve, the banking helps provide centripetal force by:`, ch:[`using a component of the normal force directed toward the center of the curve`,`reducing the radius of the turn`,`eliminating the need for any friction in every case`,`increasing the local strength of gravity`], ans:0, exp:`Banking tilts the road surface so that part of the normal force points horizontally toward the center of the curve, helping supply centripetal force in addition to (or instead of) friction.` },
      { q:`Which of the following is an everyday example of centripetal acceleration?`, ch:[`A satellite orbiting Earth`,`A book resting motionless on a table`,`A car driving straight down a highway`,`A ball rolling in a straight line on flat ground`], ans:0, exp:`A satellite in orbit is constantly accelerating toward Earth's center due to gravity, even though its speed may stay roughly constant, which is a textbook case of centripetal acceleration.` },
      { q:`Angular velocity is typically measured in units of:`, ch:[`newtons`,`joules`,`meters per second`,`radians per second`], ans:3, exp:`Angular velocity describes how fast an angle is swept out over time and is measured in radians per second (rad/s).` },
      { q:`The relationship between linear speed v, angular velocity (omega), and radius r is:`, ch:[`v = omega + r`,`v = omega x r`,`v = omega / r`,`v = omega - r`], ans:1, exp:`Linear (tangential) speed equals angular velocity multiplied by the radius: v = omega x r.` },
    ]
  },
  {
    id:'cp111', cat:'Physical Sciences', title:'Torque & Simple Rotational Equilibrium', diff:'Medium',
    qs:[
      { q:`Torque is defined as:`, ch:[`force multiplied by time`,`mass multiplied by acceleration`,`force multiplied by the lever arm (perpendicular distance from the pivot)`,`force divided by distance`], ans:2, exp:`Torque = force x lever arm (the perpendicular distance from the pivot point to the line of action of the force).` },
      { q:`The SI unit of torque is the:`, ch:[`newton-meter`,`joule`,`newton`,`watt`], ans:0, exp:`Torque has units of newton-meters (N*m), since it is force (N) multiplied by distance (m).` },
      { q:`A force applied directly through the pivot point, with zero lever arm, produces:`, ch:[`maximum torque`,`zero torque`,`negative torque`,`infinite torque`], ans:1, exp:`Since torque = force x lever arm, a lever arm of zero means the torque produced is zero, regardless of the force's magnitude.` },
      { q:`For an object in rotational equilibrium, the net torque acting on it must be:`, ch:[`positive`,`zero`,`equal to the net force`,`at a maximum value`], ans:1, exp:`Rotational equilibrium requires that the sum of all torques (clockwise and counterclockwise) acting on the object equal zero, so it doesn't begin to rotate.` },
      { q:`Applying the same force farther from the pivot point (increasing the lever arm):`, ch:[`only affects the object's linear motion`,`increases the torque produced`,`decreases the torque produced`,`has no effect on the torque produced`], ans:1, exp:`Since torque is directly proportional to lever arm length, increasing the distance from the pivot increases the torque for the same applied force.` },
      { q:`A 40 kg child sits 2 m from the pivot of a balanced seesaw. Where must a 20 kg child sit on the opposite side to balance it?`, ch:[`4 m`,`8 m`,`2 m`,`1 m`], ans:0, exp:`Balance requires equal torques: 40 kg x 2 m = 80 (in mass-distance units). For the 20 kg child: 20 kg x d = 80, so d = 4 m.` },
      { q:`Torque produced by a given force is maximized when the force is applied:`, ch:[`directly at the pivot`,`parallel to the lever arm`,`perpendicular to the lever arm`,`at a 45 degree angle to the lever arm`], ans:2, exp:`Torque depends on the component of force perpendicular to the lever arm; a force applied exactly perpendicular to the arm produces the maximum possible torque for a given magnitude.` },
      { q:`A wrench is more effective at loosening a stubborn bolt when you:`, ch:[`push very close to the bolt head`,`push with less force`,`push exactly parallel to the handle`,`push at the far end of the wrench handle, increasing the lever arm`], ans:3, exp:`Pushing farther from the pivot (the bolt) increases the lever arm and therefore the torque produced for the same applied force, making the bolt easier to turn.` },
      { q:`Which of the following increases the lever arm (moment arm) of an applied force?`, ch:[`Applying the force farther from the pivot`,`Applying the force parallel to the lever, at zero angle`,`Reducing the magnitude of the force`,`Applying the force closer to the pivot`], ans:0, exp:`Moving the point of application farther from the pivot increases the perpendicular distance (lever arm), increasing the torque for the same force.` },
      { q:`In addition to zero net torque, what else must be true for an object to be in complete static equilibrium?`, ch:[`The net force on it must also be zero`,`It must be actively rotating`,`Its angular velocity must be at a maximum`,`Its total mass must be zero`], ans:0, exp:`Full static equilibrium requires both zero net force (no linear acceleration) and zero net torque (no angular acceleration).` },
      { q:`Two children on a seesaw are balanced when:`, ch:[`only one child is producing any torque`,`they sit the exact same distance from the pivot, regardless of mass`,`their masses are exactly equal`,`the sum of clockwise torques equals the sum of counterclockwise torques`], ans:3, exp:`Balance is a torque condition, not a mass condition — a heavier child sitting closer to the pivot can balance a lighter child sitting farther away.` },
      { q:`The direction of a torque (clockwise vs. counterclockwise) depends on:`, ch:[`the direction of the force relative to the pivot point`,`only the object's total mass`,`only the magnitude of the applied force`,`only the distance from the pivot`], ans:0, exp:`Whether a torque tends to rotate an object clockwise or counterclockwise depends on the direction the force is applied relative to the pivot, not just the force's size.` },
      { q:`A door is easiest to push open when you apply force:`, ch:[`right at the hinges`,`at the doorknob, farthest from the hinges`,`exactly in the middle of the door`,`only at the very top of the door`], ans:1, exp:`Pushing at the doorknob maximizes the lever arm (distance from the hinge, the pivot), producing the greatest torque for a given force, which is why doorknobs are placed far from hinges.` },
      { q:`A 10 N force is applied 0.5 m from a pivot, perpendicular to the lever arm. What torque does this produce?`, ch:[`20 N*m`,`0.5 N*m`,`5 N*m`,`10.5 N*m`], ans:2, exp:`Torque = force x lever arm = 10 N x 0.5 m = 5 N*m.` },
    ]
  },
  {
    id:'cp112', cat:'Physical Sciences', title:'Fluid Pressure & Hydraulics', diff:'Medium',
    qs:[
      { q:`Pressure is defined as:`, ch:[`mass divided by volume`,`force divided by area`,`force multiplied by area`,`force divided by distance`], ans:1, exp:`Pressure = force/area. The same force spread over a smaller area produces a greater pressure.` },
      { q:`The SI unit of pressure is the:`, ch:[`Watt`,`Pascal`,`Newton`,`Joule`], ans:1, exp:`Pressure is measured in Pascals (Pa), where 1 Pa = 1 N/m^2.` },
      { q:`Pascal's principle states that pressure applied to an enclosed fluid:`, ch:[`decreases with distance from the source`,`is lost as heat within hydraulic systems`,`is transmitted equally throughout the fluid in all directions`,`only acts downward due to gravity`], ans:2, exp:`Pascal's principle: a pressure change applied to an enclosed, incompressible fluid is transmitted undiminished to every part of the fluid and the walls of its container.` },
      { q:`In a hydraulic lift, a small force applied to a small piston can lift a much larger load on a large piston because:`, ch:[`the small piston experiences greater pressure than the large one`,`the pressure is equal on both pistons, and the larger piston has more area to generate a larger total force`,`the fluid multiplies energy out of nowhere`,`gravity is somehow weaker inside the fluid`], ans:1, exp:`Since pressure (P = F/A) is the same throughout the fluid, a larger piston area means a proportionally larger output force, even though the pressure itself is unchanged.` },
      { q:`A hydraulic system has a small piston with area 2 cm^2 and a large piston with area 20 cm^2. If a 10 N force is applied to the small piston, what force appears at the large piston?`, ch:[`1 N`,`10 N`,`200 N`,`100 N`], ans:3, exp:`Pressure is the same on both sides: P = 10 N / 2 cm^2 = 5 N/cm^2. Force on the large piston = 5 N/cm^2 x 20 cm^2 = 100 N.` },
      { q:`Atmospheric pressure at sea level is approximately:`, ch:[`101,325 Pa`,`1,000 Pa`,`1 Pa`,`1 N`], ans:0, exp:`Standard atmospheric pressure at sea level is about 101,325 Pa, also expressed as 1 atmosphere (atm).` },
      { q:`Pressure within a static fluid increases with:`, ch:[`decreasing depth`,`decreasing density only, regardless of depth`,`increasing depth`,`temperature only`], ans:2, exp:`As you go deeper into a fluid, there is more fluid (and weight) pressing down from above, so pressure increases with depth.` },
      { q:`Which formula correctly gives the pressure due to a fluid column of depth h?`, ch:[`P = rho x g x h (plus atmospheric pressure, if open to air)`,`P = rho / (g x h)`,`P = F x A`,`P = m x g`], ans:0, exp:`Fluid pressure at depth h is P = rho x g x h, where rho is the fluid's density and g is gravitational acceleration; total absolute pressure adds atmospheric pressure if the fluid surface is exposed to air.` },
      { q:`A barometer is a device used to measure:`, ch:[`temperature`,`fluid flow rate`,`density`,`atmospheric pressure`], ans:3, exp:`Barometers use a column of liquid (traditionally mercury) to measure the surrounding atmospheric pressure.` },
      { q:`In a hydraulic brake system, pressing the brake pedal (a smaller area) creates pressure that is transmitted to:`, ch:[`a smaller-area brake pad, producing an even smaller force`,`the tires directly, bypassing the brake pads`,`the engine directly`,`a larger-area brake pad, producing a much greater force`], ans:3, exp:`Because pressure is transmitted equally, the larger brake pad piston experiences a much greater force than what was applied at the pedal, multiplying the braking force.` },
      { q:`Gauge pressure differs from absolute pressure in that gauge pressure:`, ch:[`excludes (subtracts out) atmospheric pressure`,`is always numerically higher than absolute pressure`,`includes atmospheric pressure in its value`,`is measured in completely different units`], ans:0, exp:`Gauge pressure = absolute pressure - atmospheric pressure, which is what most pressure gauges (like tire gauges) actually display.` },
      { q:`A hydraulic system cannot multiply the total work or energy output because:`, ch:[`the smaller piston must move a proportionally greater distance than the larger piston moves`,`distance is also multiplied along with force`,`energy is created within the fluid`,`pressure is not actually conserved in the system`], ans:0, exp:`Conservation of energy holds: while force is multiplied at the larger piston, that piston moves a correspondingly shorter distance, so total work in equals total work out (ignoring friction).` },
      { q:`Which device relies directly on Pascal's principle to operate?`, ch:[`A hydraulic car jack`,`A pulley system using only fixed pulleys`,`A see-saw`,`A simple pendulum`], ans:0, exp:`Hydraulic jacks use an enclosed fluid to transmit and amplify force from a small input piston to a large output piston, a direct application of Pascal's principle.` },
      { q:`If the pressure applied at one point in an enclosed, incompressible fluid increases by 500 Pa, the pressure at every other point in that fluid:`, ch:[`also increases by 500 Pa`,`decreases by 500 Pa`,`stays exactly the same`,`drops to zero`], ans:0, exp:`According to Pascal's principle, any pressure change applied to an enclosed fluid is transmitted equally throughout the entire fluid.` },
    ]
  },
  {
    id:'cp113', cat:'Physical Sciences', title:'Buoyancy & Archimedes Principle', diff:'Medium',
    qs:[
      { q:`Archimedes' principle states that the buoyant force on an object equals:`, ch:[`the density of the surrounding fluid`,`the total volume of the object`,`the weight of the fluid displaced by the object`,`the weight of the object itself`], ans:2, exp:`Archimedes' principle: the upward buoyant force on a submerged (or floating) object equals the weight of the fluid it displaces.` },
      { q:`An object will float in a fluid when:`, ch:[`its weight is balanced by the buoyant force at some level of submersion`,`it has zero mass`,`its density is greater than the fluid's density`,`its density exactly equals the fluid's density`], ans:0, exp:`An object floats when it can displace enough fluid that the resulting buoyant force equals its weight, which happens automatically for any object less dense than the fluid.` },
      { q:`A large steel ship floats on water mainly because:`, ch:[`steel physically cannot sink`,`the ship's hollow shape displaces enough water that its overall average density is less than water`,`water pressure pushes it upward uniformly regardless of shape`,`steel itself is less dense than water`], ans:1, exp:`Even though steel is denser than water, the ship's hull shape encloses a large volume of air, making the ship's overall average density (mass divided by total volume, including the air space) less than water's.` },
      { q:`An object that sinks when placed in water has a density:`, ch:[`that is irrelevant to whether it sinks`,`greater than that of water`,`equal to that of water`,`less than that of water`], ans:1, exp:`Objects denser than the fluid they're placed in cannot displace enough fluid weight to support their own weight, so they sink.` },
      { q:`If an object floats with 60% of its volume submerged, its density is what fraction of the fluid's density?`, ch:[`40%`,`200%`,`100%`,`60%`], ans:3, exp:`At equilibrium, the weight of displaced fluid equals the object's weight, so the object's density equals the fraction of its volume submerged times the fluid's density — here, 60%.` },
      { q:`The buoyant force on a fully submerged object depends on:`, ch:[`the object's weight alone`,`the density of the fluid and the volume of fluid displaced`,`the object's temperature`,`the object's shape alone, regardless of volume`], ans:1, exp:`Buoyant force = (fluid density) x (volume displaced) x g, so it depends on the fluid's density and how much volume the object displaces, not directly on the object's own weight.` },
      { q:`A fish adjusts its buoyancy by using its swim bladder to:`, ch:[`change the volume of gas inside, adjusting its average density`,`change its total mass instantly`,`change the surrounding water's temperature`,`swim faster to compensate`], ans:0, exp:`By inflating or deflating its swim bladder, a fish changes its overall volume (and thus average density) without significantly changing its mass, allowing it to rise, sink, or hover.` },
      { q:`An object weighs 50 N in air and 30 N when fully submerged in water. What is the buoyant force acting on it?`, ch:[`80 N`,`30 N`,`50 N`,`20 N`], ans:3, exp:`Buoyant force = weight in air - apparent weight submerged = 50 N - 30 N = 20 N.` },
      { q:`An object whose density is exactly equal to the surrounding fluid's density will:`, ch:[`float on the surface`,`remain suspended in the fluid at any depth (neutral buoyancy)`,`sink all the way to the bottom`,`rise completely out of the fluid`], ans:1, exp:`When density exactly matches the fluid, the buoyant force exactly balances gravity at any depth, so the object neither rises nor sinks — a state called neutral buoyancy.` },
      { q:`A hot air balloon rises because:`, ch:[`it actively repels the surrounding air`,`the heated air inside is less dense than the surrounding cooler air`,`it has literally zero weight`,`the balloon material itself is lighter than air`], ans:1, exp:`Heating the air inside the balloon makes it expand and become less dense than the cooler air outside, creating a buoyant force greater than the balloon's total weight.` },
      { q:`Because salt water is denser than fresh water, a floating object will sit:`, ch:[`at exactly the same level in both`,`higher (less submerged) in salt water than in fresh water`,`only floats in fresh water, never in salt water`,`lower in salt water than in fresh water`], ans:1, exp:`Since salt water is denser, a smaller volume needs to be displaced to equal the object's weight, so the object floats higher (less submerged) in salt water.` },
      { q:`The apparent weight of a submerged object equals:`, ch:[`its true weight minus the buoyant force`,`always zero`,`the buoyant force alone`,`its true weight plus the buoyant force`], ans:0, exp:`The buoyant force acts opposite to gravity, so the apparent (measured) weight while submerged is reduced by the amount of the buoyant force.` },
      { q:`Which factor does NOT directly affect the buoyant force on a submerged object?`, ch:[`Volume of fluid displaced`,`The object's own weight`,`Acceleration due to gravity`,`Density of the fluid`], ans:1, exp:`Buoyant force depends on fluid density, displaced volume, and gravitational acceleration (F = rho_fluid x V_displaced x g) — the object's own weight doesn't directly appear in this formula.` },
      { q:`A block of wood with density 600 kg/m^3 floats in water (density 1,000 kg/m^3). What fraction of the block is submerged?`, ch:[`0.4`,`0.6`,`0.167`,`1.0`], ans:1, exp:`Fraction submerged = object density / fluid density = 600/1,000 = 0.6, meaning 60% of the block is underwater.` },
    ]
  },
  {
    id:'cp114', cat:'Physical Sciences', title:'Specific Heat & Phase Changes', diff:'Medium',
    qs:[
      { q:`Specific heat capacity is defined as:`, ch:[`the energy needed to melt 1 gram of a substance`,`the total heat content of an object`,`the energy needed to raise the temperature of 1 gram of a substance by 1 degree Celsius`,`the temperature at which a substance boils`], ans:2, exp:`Specific heat capacity (c) measures how much energy is required to raise the temperature of one gram of a substance by one degree Celsius.` },
      { q:`Which formula relates heat (q), mass (m), specific heat (c), and temperature change (deltaT)?`, ch:[`q = m/c x deltaT`,`q = c / (m x deltaT)`,`q = m x c x deltaT`,`q = m x c / deltaT`], ans:2, exp:`The heat equation is q = m x c x deltaT, where deltaT is the change in temperature.` },
      { q:`Water has a relatively high specific heat capacity, which means it:`, ch:[`conducts electricity especially well`,`resists changes in temperature, absorbing or releasing a lot of heat per degree of change`,`heats up and cools down very quickly`,`has an unusually low boiling point`], ans:1, exp:`Water's high specific heat means it takes a large amount of energy to change its temperature, which is why large bodies of water moderate the climate of nearby land.` },
      { q:`During a phase change, like melting or boiling, the temperature of a substance:`, ch:[`increases steadily`,`becomes negative`,`decreases steadily`,`remains constant while heat is added or removed`], ans:3, exp:`While a substance is changing phase, added or removed heat goes into breaking or forming intermolecular bonds rather than changing kinetic energy, so temperature stays constant.` },
      { q:`The energy required to change 1 gram of a solid into a liquid at its melting point is called the:`, ch:[`heat of fusion (latent heat of melting)`,`specific heat`,`heat of vaporization`,`heat of sublimation`], ans:0, exp:`Heat of fusion is the energy needed to convert a solid to a liquid at constant temperature (its melting point).` },
      { q:`The energy required to change 1 gram of a liquid into a gas at its boiling point is called the:`, ch:[`heat of fusion`,`heat capacity`,`heat of vaporization (latent heat of boiling)`,`specific heat`], ans:2, exp:`Heat of vaporization is the energy needed to convert a liquid into a gas at constant temperature (its boiling point).` },
      { q:`Sublimation is the direct phase change from:`, ch:[`solid to liquid`,`liquid to gas`,`solid directly to gas, skipping the liquid phase`,`gas directly to solid`], ans:2, exp:`Sublimation occurs when a solid converts directly into a gas without passing through a liquid phase, as dry ice (solid CO2) does at room temperature.` },
      { q:`Deposition is the direct phase change from:`, ch:[`liquid to solid`,`gas directly to solid, skipping the liquid phase`,`solid to gas`,`solid to liquid`], ans:1, exp:`Deposition is the reverse of sublimation — a gas converts directly into a solid, as seen when frost forms directly from water vapor.` },
      { q:`100 g of water is heated from 20 C to 40 C (specific heat of water ≈ 4.18 J/g*C). How much heat is absorbed?`, ch:[`836 J`,`4,180 J`,`8,360 J`,`83,600 J`], ans:2, exp:`q = m x c x deltaT = 100 g x 4.18 J/g*C x 20 C = 8,360 J.` },
      { q:`During condensation, a gas releases energy and turns into a:`, ch:[`liquid`,`plasma`,`different gas`,`solid`], ans:0, exp:`Condensation is the reverse of vaporization, where a gas releases energy and transitions into a liquid.` },
      { q:`A substance with a low specific heat will change temperature:`, ch:[`slowly, for a given amount of added heat`,`only when it is melting`,`never, regardless of heat added`,`quickly, for a given amount of added heat`], ans:3, exp:`A low specific heat means less energy is required to change its temperature by a given amount, so it heats up or cools down relatively quickly.` },
      { q:`On a heating curve (temperature vs. heat added) for water, the flat horizontal plateaus represent:`, ch:[`chemical reactions occurring`,`phase changes (melting or boiling), where temperature stays constant`,`periods of temperature increase`,`periods of cooling`], ans:1, exp:`During a phase change, all added heat goes toward breaking intermolecular bonds rather than raising temperature, producing a flat plateau on the heating curve.` },
      { q:`Evaporation differs from boiling mainly in that evaporation:`, ch:[`requires no energy input at all`,`can occur at the surface of a liquid at temperatures below its boiling point`,`only occurs exactly at the boiling point`,`only occurs in solids, not liquids`], ans:1, exp:`Evaporation happens at the surface of a liquid at any temperature, as the fastest-moving surface molecules escape into the gas phase, while boiling requires reaching the boiling point throughout the liquid.` },
      { q:`Given that water's specific heat (about 4.18 J/g*C) is much higher than iron's (about 0.45 J/g*C), which requires more energy to raise its temperature by 1 degree C, per gram?`, ch:[`They require exactly the same energy`,`Water`,`Neither substance requires any energy`,`Iron`], ans:1, exp:`Water's much higher specific heat means it requires significantly more energy per gram to achieve the same 1-degree temperature increase compared to iron.` },
    ]
  },
  {
    id:'cp115', cat:'Physical Sciences', title:'Series and Parallel Circuits', diff:'Medium',
    qs:[
      { q:`In a series circuit, the current:`, ch:[`is zero at certain points`,`varies at each component`,`is highest only at the battery`,`is the same through every component`], ans:3, exp:`Because a series circuit provides only a single path for current, the same current flows through every component in the loop.` },
      { q:`In a parallel circuit, the voltage across each branch:`, ch:[`must be added together to get the source voltage`,`is always zero`,`is the same across each parallel branch`,`varies depending on the branch`], ans:2, exp:`All branches of a parallel circuit are connected directly across the same two nodes, so each branch experiences the same voltage as the source.` },
      { q:`Total resistance in a series circuit is found by:`, ch:[`multiplying the resistances together`,`taking the reciprocal of the sum of reciprocals`,`averaging the resistances`,`adding the individual resistances`], ans:3, exp:`Series resistances simply add: Rtotal = R1 + R2 + ...` },
      { q:`Total resistance in a parallel circuit is found using the formula:`, ch:[`1/Rtotal = 1/R1 + 1/R2 + ...`,`Rtotal = R1 x R2`,`Rtotal always equals the largest individual resistor`,`adding the resistances directly`], ans:0, exp:`For resistors in parallel, the reciprocals of the resistances add: 1/Rtotal = 1/R1 + 1/R2 + ...` },
      { q:`If one bulb burns out (creating a break) in a series circuit, the other bulbs:`, ch:[`glow brighter than before`,`are completely unaffected`,`also go out, because the single current path is broken`,`continue to glow normally`], ans:2, exp:`Since a series circuit has only one path, a break anywhere stops current everywhere in the loop, turning off all the bulbs.` },
      { q:`If one bulb burns out in a parallel circuit, the other bulbs on separate branches:`, ch:[`continue to glow, since their own circuit path remains intact`,`glow much brighter than before`,`all go out as well`,`get noticeably dimmer`], ans:0, exp:`Each branch of a parallel circuit is an independent path, so a break in one branch doesn't affect current flow through the other branches.` },
      { q:`Adding more resistors in series to a circuit:`, ch:[`only affects the source voltage`,`increases the total resistance`,`decreases the total resistance`,`has no effect on total resistance`], ans:1, exp:`Since series resistances simply add together, adding more resistors in series always increases the total resistance.` },
      { q:`Adding more resistors in parallel to a circuit:`, ch:[`doubles the source voltage`,`increases the total resistance`,`decreases the total resistance`,`has no effect on total resistance`], ans:2, exp:`Adding parallel paths gives current more routes to flow through, which always decreases the overall (equivalent) resistance of the combination.` },
      { q:`Household electrical outlets are typically wired in:`, ch:[`parallel`,`neither configuration`,`a mix that always causes failures`,`series`], ans:0, exp:`Outlets are wired in parallel so that each appliance receives the full source voltage and can operate independently of other devices.` },
      { q:`In a series circuit with a 12 V battery and two equal resistors, what is the voltage across each resistor?`, ch:[`6 V each`,`12 V each`,`0 V each`,`24 V each`], ans:0, exp:`In series, the total voltage divides among the resistors according to their resistance; with two equal resistors, the 12 V splits evenly into 6 V each.` },
      { q:`Two resistors of 6 ohms and 3 ohms are connected in parallel. What is their total resistance?`, ch:[`4.5 ohms`,`18 ohms`,`2 ohms`,`9 ohms`], ans:2, exp:`1/Rtotal = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2, so Rtotal = 2 ohms.` },
      { q:`Two resistors of 4 ohms and 6 ohms are connected in series. What is their total resistance?`, ch:[`24 ohms`,`2.4 ohms`,`10 ohms`,`1.5 ohms`], ans:2, exp:`Series resistances simply add: 4 ohms + 6 ohms = 10 ohms.` },
      { q:`Old-style Christmas lights wired in series illustrate a disadvantage because:`, ch:[`the lights become too bright`,`they use far too much energy`,`they cannot connect to a standard power source`,`one burned-out bulb causes the entire string of lights to go dark`], ans:3, exp:`Since series circuits have only one current path, a single broken bulb interrupts the whole string, which is why modern light strings use parallel wiring instead.` },
      { q:`A short circuit typically occurs when:`, ch:[`voltage drops to exactly zero everywhere`,`current stops flowing entirely`,`current finds an unintended path of very low resistance, bypassing the normal load`,`resistance in the circuit becomes very high`], ans:2, exp:`A short circuit provides a low-resistance shortcut for current, which can cause a dangerous surge in current and overheating if not interrupted by a fuse or breaker.` },
    ]
  },
  {
    id:'cp116', cat:'Physical Sciences', title:'Electromagnets & the Magnetic Field of Currents', diff:'Medium',
    qs:[
      { q:`A current-carrying wire produces:`, ch:[`no field of any kind`,`an electric field only`,`only heat, no field`,`a magnetic field that circles around the wire`], ans:3, exp:`Moving electric charge (current) generates a magnetic field that forms concentric circles around the wire, a phenomenon first observed by Hans Christian Oersted.` },
      { q:`The right-hand rule for a straight current-carrying wire is used to determine:`, ch:[`the resistance of the wire`,`the voltage across the wire`,`the direction of current flow`,`the direction of the magnetic field circling the wire`], ans:3, exp:`Pointing the right thumb in the direction of conventional current, the curled fingers show the direction the magnetic field circles around the wire.` },
      { q:`Wrapping a current-carrying wire into a coil (solenoid) does what to the magnetic field inside the coil?`, ch:[`Reverses its direction randomly`,`Concentrates and strengthens the field inside the coil`,`Cancels it out completely`,`Makes the inside field identical to the field outside`], ans:1, exp:`Coiling the wire causes the magnetic fields from each loop to add together inside the coil, producing a much stronger, more concentrated field than a single straight wire.` },
      { q:`Adding an iron core inside a solenoid:`, ch:[`converts the magnetic field into an electric field`,`strengthens the magnetic field by concentrating the field lines`,`weakens the magnetic field`,`has no effect on field strength`], ans:1, exp:`Iron is easily magnetized and concentrates magnetic field lines within it, significantly increasing the strength of the electromagnet.` },
      { q:`An electromagnet differs from a permanent magnet mainly in that an electromagnet's field:`, ch:[`can be turned on and off by controlling the electric current`,`is always weaker than a permanent magnet`,`never has distinct poles`,`can never be turned off`], ans:0, exp:`Because the magnetic field of an electromagnet depends on current flow, switching the current on or off turns the magnetic field on or off.` },
      { q:`Increasing the current through a solenoid:`, ch:[`has no effect on the field`,`increases the magnetic field strength`,`only affects the coil's resistance`,`decreases the magnetic field strength`], ans:1, exp:`The strength of a solenoid's magnetic field is directly proportional to the current flowing through it.` },
      { q:`Increasing the number of turns (loops) of wire in a solenoid:`, ch:[`has no effect on the field`,`decreases the magnetic field strength`,`increases the magnetic field strength`,`reduces the current in the wire`], ans:2, exp:`More turns mean more overlapping loops contributing to the field, so the magnetic field strength increases with the number of turns per unit length.` },
      { q:`Electric doorbells, electric motors, and MRI machines all commonly rely on:`, ch:[`permanent magnets exclusively`,`no magnetic principles at all`,`static electricity only`,`electromagnets`], ans:3, exp:`These devices all use electromagnets, whose field strength and direction can be controlled electrically, unlike fixed permanent magnets.` },
      { q:`According to the right-hand rule, the magnetic field direction around a straight current-carrying wire is:`, ch:[`circular, wrapping around the wire`,`parallel to the current`,`completely random`,`opposite to the direction of current`], ans:0, exp:`The magnetic field forms closed concentric circles around the wire, perpendicular to the direction of current flow.` },
      { q:`A basic electric motor converts:`, ch:[`electrical energy into mechanical energy (rotational motion)`,`chemical energy into sound`,`heat energy into light`,`mechanical energy into electrical energy`], ans:0, exp:`Electric motors use current-carrying coils in a magnetic field to produce torque, converting electrical energy into rotational mechanical motion.` },
      { q:`A basic electric generator converts:`, ch:[`mechanical energy into electrical energy via electromagnetic induction`,`sound energy into electricity`,`light energy into heat`,`electrical energy into mechanical motion`], ans:0, exp:`Generators spin a coil within a magnetic field (or vice versa), inducing a current — the reverse process of a motor.` },
      { q:`Which combination would create the strongest electromagnet?`, ch:[`Low current, few turns, no iron core`,`High current, few turns, no iron core`,`Low current, many turns, no iron core`,`High current, many turns, iron core`], ans:3, exp:`Field strength increases with current, number of turns, and the presence of an iron core, so combining all three factors produces the strongest possible electromagnet.` },
      { q:`Electromagnetic relays and circuit breakers often use electromagnets to:`, ch:[`store chemical energy`,`measure ambient temperature`,`mechanically open or close a switch when current flows`,`generate visible light`], ans:2, exp:`In a relay, current through an electromagnet coil creates a magnetic field that physically pulls a metal switch open or closed, allowing a small control current to switch a much larger circuit.` },
      { q:`Unlike a permanent bar magnet, an electromagnet's magnetic poles can be reversed simply by:`, ch:[`physically flipping the magnet over`,`adding more iron to the core`,`heating the coil significantly`,`reversing the direction of current flow through the coil`], ans:3, exp:`Since the magnetic field direction depends on the direction of current flow (right-hand rule), reversing the current reverses which end of the coil is the north or south pole.` },
    ]
  },
  {
    id:'cp117', cat:'Physical Sciences', title:'Color Perception & Light Mixing', diff:'Easy',
    qs:[
      { q:`Which set correctly lists the primary colors of light used in additive color mixing?`, ch:[`Red, green, blue`,`Red, yellow, blue`,`Black, white, gray`,`Cyan, magenta, yellow`], ans:0, exp:`In additive color mixing (combining light), the primary colors are red, green, and blue (RGB), as used in screens and displays.` },
      { q:`Mixing all three primary colors of light together at full intensity produces:`, ch:[`gray`,`red`,`white light`,`black`], ans:2, exp:`Combining red, green, and blue light at equal, full intensity produces white light, since all visible wavelengths are represented.` },
      { q:`Which set is traditionally taught as the primary colors of pigment (subtractive mixing) in art class?`, ch:[`Cyan, magenta, yellow`,`Orange, green, violet`,`Red, yellow, blue`,`Red, green, blue`], ans:2, exp:`Red, yellow, and blue are the traditional artist's primary pigment colors, though printers technically use cyan, magenta, and yellow for more accurate subtractive mixing.` },
      { q:`An object appears red under white light mainly because it:`, ch:[`emits red light on its own`,`reflects all colors equally`,`absorbs all colors except red, which it reflects`,`absorbs only red light and reflects the rest`], ans:2, exp:`A red object absorbs most wavelengths of incoming white light but reflects red wavelengths back to our eyes, which is why it appears red.` },
      { q:`A black object absorbs:`, ch:[`only blue light`,`nearly all visible light wavelengths`,`only red light`,`no visible light at all`], ans:1, exp:`Black objects absorb most or all of the visible light that strikes them, reflecting very little back, which is why they appear black.` },
      { q:`A white object reflects:`, ch:[`only ultraviolet light`,`all visible light wavelengths roughly equally`,`no visible light at all`,`only green light`], ans:1, exp:`White objects reflect nearly all wavelengths of visible light roughly equally, which our eyes perceive as white.` },
      { q:`The sky appears blue during the day mainly because of:`, ch:[`reflection of sunlight off clouds`,`Rayleigh scattering, in which shorter (blue) wavelengths scatter more strongly off air molecules`,`blue pigments naturally present in the atmosphere`,`selective absorption of blue light by nitrogen molecules`], ans:1, exp:`Shorter wavelengths like blue scatter more efficiently off the small molecules in the atmosphere (Rayleigh scattering), spreading blue light across the sky.` },
      { q:`A prism separates white light into a spectrum of colors because:`, ch:[`different wavelengths of light refract by different amounts when passing through the glass`,`light is selectively absorbed at each color`,`only red light is actually able to pass through glass`,`the prism adds color to otherwise colorless light`], ans:0, exp:`Different wavelengths bend by slightly different amounts as they refract through the prism (dispersion), spreading white light into its component colors.` },
      { q:`Combining complementary colors of light typically produces:`, ch:[`a darker, more saturated color`,`no visible change at all`,`always green light`,`white light`], ans:3, exp:`Complementary colors of light (like red and cyan) combine to produce white light because together they cover the full visible spectrum.` },
      { q:`In the visible spectrum, which color has the longest wavelength?`, ch:[`Green`,`Blue`,`Red`,`Violet`], ans:2, exp:`Red light has the longest wavelength (and lowest energy) of the visible spectrum, while violet has the shortest.` },
      { q:`In the visible spectrum, which color has the shortest wavelength?`, ch:[`Yellow`,`Orange`,`Red`,`Violet`], ans:3, exp:`Violet light has the shortest wavelength (and highest energy) within the visible spectrum.` },
      { q:`Mixing cyan and magenta light together (additive mixing) approximately produces:`, ch:[`white`,`blue`,`black`,`yellow`], ans:1, exp:`Cyan (green+blue) and magenta (red+blue) light share blue in common, and their combination produces a blue-dominant result.` },
      { q:`A rainbow forms when sunlight is refracted, reflected, and dispersed by:`, ch:[`ice crystals exclusively`,`dust particles in the air`,`pollution particles`,`water droplets suspended in the air`], ans:3, exp:`Sunlight enters spherical water droplets, refracts, reflects internally, and refracts again as it exits, spreading the light into the colors of the rainbow.` },
      { q:`Colored filters work by:`, ch:[`emitting their own colored light`,`reflecting all incoming light`,`adding extra energy to the light passing through`,`transmitting only certain wavelengths of light while absorbing the rest`], ans:3, exp:`A colored filter selectively absorbs most wavelengths while allowing only a narrow range of wavelengths to pass through, giving transmitted light its characteristic color.` },
    ]
  },
  {
    id:'cp118', cat:'Physical Sciences', title:'Weathering & Erosion', diff:'Easy',
    qs:[
      { q:`Weathering is best defined as:`, ch:[`the transport of rock material from one location to another`,`the melting of solid rock into magma`,`the breakdown of rocks and minerals at or near Earth's surface`,`the formation of new rock directly from magma`], ans:2, exp:`Weathering breaks rock down in place, either physically or chemically, without necessarily moving the material anywhere.` },
      { q:`Erosion is best defined as:`, ch:[`the breakdown of rock in place`,`the cooling and solidifying of magma`,`the transport of weathered material by agents like wind, water, ice, or gravity`,`the compaction of sediment into solid rock`], ans:2, exp:`Erosion is the process of moving weathered sediment from one place to another, driven by agents such as rivers, wind, glaciers, or gravity.` },
      { q:`Mechanical (physical) weathering changes rock by:`, ch:[`altering its chemical composition`,`breaking it into smaller pieces without changing its chemical composition`,`melting it into magma`,`dissolving it completely`], ans:1, exp:`Mechanical weathering physically fractures rock into smaller pieces (like frost wedging or abrasion) while the mineral composition stays the same.` },
      { q:`Chemical weathering changes rock by:`, ch:[`compacting it under pressure`,`freezing it solid`,`breaking it apart physically only`,`altering its mineral composition through chemical reactions`], ans:3, exp:`Chemical weathering involves reactions (such as oxidation or dissolution by acidic water) that transform the minerals in a rock into new substances.` },
      { q:`Frost wedging (ice wedging), where water seeps into cracks and expands as it freezes, is an example of:`, ch:[`mechanical weathering`,`chemical weathering`,`metamorphism`,`deposition`], ans:0, exp:`Frost wedging physically breaks rock apart as freezing water expands in cracks, making it a form of mechanical weathering.` },
      { q:`Acid rain dissolving limestone is an example of:`, ch:[`mechanical weathering`,`lithification`,`chemical weathering`,`deposition`], ans:2, exp:`This process changes the limestone's chemical composition through a reaction with acid, which is chemical weathering.` },
      { q:`Which of these is NOT typically an agent responsible for erosion?`, ch:[`Wind`,`Running water`,`Magma`,`Glaciers`], ans:2, exp:`Magma is molten rock beneath the surface and is not an erosional agent; wind, water, and glaciers are all classic agents of erosion.` },
      { q:`Deposition occurs when an erosional agent, such as a river, loses energy and:`, ch:[`melts sediment into new rock`,`drops the sediment it was previously carrying`,`dissolves rock completely`,`picks up new sediment to carry`], ans:1, exp:`As flowing water, wind, or ice slows down and loses energy, it can no longer keep sediment suspended or moving, so it deposits the material.` },
      { q:`Sediment deposited by a river at its mouth, forming a fan-shaped landform, creates a:`, ch:[`canyon`,`glacier`,`delta`,`volcano`], ans:2, exp:`Deltas form where a river slows as it enters a larger body of water, depositing sediment in a characteristic fan shape.` },
      { q:`Root growth from plants that gradually cracks rocks apart is an example of:`, ch:[`biological (mechanical) weathering`,`chemical weathering`,`erosion, but not weathering`,`deposition`], ans:0, exp:`Roots growing into cracks and expanding them apart physically break rock without changing its chemical makeup, making it a mechanical (biological) form of weathering.` },
      { q:`Which factor generally increases the rate of weathering?`, ch:[`Removing all sources of water`,`Dry, stable climates with little temperature change`,`Increased surface area of exposed rock, such as from fracturing`,`Keeping the rock permanently frozen with no freeze-thaw cycling`], ans:2, exp:`More exposed surface area gives chemical and physical weathering agents more contact with the rock, speeding up the overall weathering process.` },
      { q:`Glaciers cause erosion primarily by:`, ch:[`evaporating surrounding water`,`dissolving rock chemically`,`having no erosional effect at all`,`plucking rock fragments and abrading (grinding) surfaces as the ice slowly moves`], ans:3, exp:`Moving glacial ice picks up (plucks) rock fragments and drags embedded rocks across the landscape, grinding and scouring the surface beneath it.` },
      { q:`Wind erosion tends to be most significant in which environment?`, ch:[`Polar ice caps exclusively`,`Arid deserts with little vegetation`,`Deep ocean trenches`,`Dense, humid rainforests`], ans:1, exp:`Sparse vegetation and dry, loose sediment in deserts make them especially vulnerable to wind erosion, unlike vegetated regions where roots hold soil in place.` },
      { q:`The process by which loose sediment becomes solid rock through compaction and cementation is called:`, ch:[`lithification`,`erosion`,`weathering`,`sublimation`], ans:0, exp:`Lithification is the process that transforms loose sediment into solid sedimentary rock as layers compact and minerals cement the grains together.` },
    ]
  },
  {
    id:'cp119', cat:'Physical Sciences', title:'The Electromagnetic Spectrum for Beginners', diff:'Easy',
    qs:[
      { q:`All electromagnetic waves travel through a vacuum at:`, ch:[`the same speed (the speed of light)`,`the speed of sound`,`different speeds depending on their wavelength`,`zero speed`], ans:0, exp:`Regardless of wavelength or frequency, all electromagnetic waves travel at the same speed in a vacuum: about 3 x 10^8 m/s, the speed of light.` },
      { q:`Which type of electromagnetic wave has the longest wavelength?`, ch:[`Gamma rays`,`Radio waves`,`Ultraviolet`,`X-rays`], ans:1, exp:`Radio waves have the longest wavelengths (and lowest energy and frequency) of all electromagnetic radiation.` },
      { q:`Which type of electromagnetic wave has the shortest wavelength (and highest energy)?`, ch:[`Visible light`,`Gamma rays`,`Radio waves`,`Microwaves`], ans:1, exp:`Gamma rays have the shortest wavelengths and the highest energy and frequency of any type of electromagnetic radiation.` },
      { q:`As wavelength increases across the electromagnetic spectrum, frequency:`, ch:[`increases`,`decreases`,`becomes zero`,`stays exactly the same`], ans:1, exp:`Wavelength and frequency are inversely related (c = f x wavelength, with c constant), so as wavelength increases, frequency decreases.` },
      { q:`Visible light occupies which part of the electromagnetic spectrum?`, ch:[`Between ultraviolet and infrared`,`Beyond gamma rays`,`Between radio waves and microwaves`,`Below (longer wavelength than) radio waves`], ans:0, exp:`Visible light sits in a narrow band of the spectrum between infrared (longer wavelength) and ultraviolet (shorter wavelength) radiation.` },
      { q:`Which type of electromagnetic radiation is used in microwave ovens to heat food?`, ch:[`Visible light`,`Gamma rays`,`X-rays`,`Microwaves`], ans:3, exp:`Microwave ovens use microwave radiation, which is efficiently absorbed by water molecules in food, causing them to vibrate and generate heat.` },
      { q:`Which type of electromagnetic radiation is commonly used for medical imaging of bones?`, ch:[`Radio waves`,`Visible light`,`Infrared`,`X-rays`], ans:3, exp:`X-rays have enough energy to pass through soft tissue but are absorbed by denser bone, producing the contrast used in medical X-ray imaging.` },
      { q:`Ultraviolet (UV) radiation from the Sun is primarily responsible for:`, ch:[`sunburn and skin damage`,`cell phone communication signals`,`radio broadcasting`,`cooking food efficiently`], ans:0, exp:`UV radiation carries enough energy to damage skin cells, leading to sunburn and increased risk of skin cancer with excessive exposure.` },
      { q:`Infrared radiation is most closely associated with:`, ch:[`gamma decay processes`,`radio communication`,`X-ray medical imaging`,`heat/thermal energy, which we sense as warmth`], ans:3, exp:`Infrared radiation is emitted by warm objects and is commonly perceived by our skin as radiant heat.` },
      { q:`Which lists the electromagnetic spectrum correctly, in order from lowest to highest energy?`, ch:[`Gamma, X-ray, UV, visible, infrared, microwave, radio`,`Visible, UV, infrared, radio, gamma, X-ray`,`Radio, microwave, infrared, visible, UV, X-ray, gamma`,`Radio, gamma, X-ray, UV, visible, infrared, microwave`], ans:2, exp:`From lowest to highest energy (longest to shortest wavelength), the correct order is radio, microwave, infrared, visible, ultraviolet, X-ray, and gamma rays.` },
      { q:`Radio waves are commonly used for:`, ch:[`sterilizing medical equipment`,`cooking food`,`medical imaging of bones`,`broadcasting communication signals, such as radio, TV, and cell phone signals`], ans:3, exp:`Radio waves have relatively low energy and long wavelengths, making them well-suited for carrying communication signals over long distances.` },
      { q:`Which equation correctly relates the speed of light c, frequency f, and wavelength (lambda)?`, ch:[`c = f + lambda`,`c = f x lambda`,`c = lambda / f`,`c = f / lambda`], ans:1, exp:`The wave equation for electromagnetic radiation is c = f x lambda, meaning speed equals frequency times wavelength.` },
      { q:`Gamma rays are typically produced by:`, ch:[`nuclear reactions and radioactive decay`,`household electronic devices`,`radio antennas`,`ordinary light bulbs`], ans:0, exp:`Gamma rays are high-energy photons emitted during nuclear processes, such as radioactive decay or nuclear fission and fusion reactions.` },
      { q:`Visible light makes up only a small portion of the full electromagnetic spectrum because:`, ch:[`it is the only type of electromagnetic radiation that actually exists`,`visible light travels slower than other electromagnetic waves`,`all other electromagnetic waves are entirely man-made`,`human eyes evolved to detect only a narrow range of wavelengths`], ans:3, exp:`Our eyes contain receptors sensitive to only a narrow band of wavelengths, which is why we perceive just a small slice of the full electromagnetic spectrum as "visible."` },
    ]
  },
  {
    id:'cp120', cat:'Physical Sciences', title:'The Solar System & Planetary Motion', diff:'Easy',
    qs:[
      { q:`Which planet is closest to the Sun?`, ch:[`Mars`,`Venus`,`Mercury`,`Earth`], ans:2, exp:`Mercury is the innermost planet in our solar system, orbiting closest to the Sun.` },
      { q:`Which planet is commonly known as the "Red Planet"?`, ch:[`Mars`,`Venus`,`Jupiter`,`Saturn`], ans:0, exp:`Mars appears reddish due to iron oxide (rust) covering much of its surface, earning it the nickname "Red Planet."` },
      { q:`Which is the largest planet in our solar system?`, ch:[`Jupiter`,`Saturn`,`Neptune`,`Earth`], ans:0, exp:`Jupiter is by far the largest planet, with a mass more than twice that of all the other planets combined.` },
      { q:`Which planet has the most prominent and visible ring system?`, ch:[`Neptune`,`Jupiter`,`Uranus`,`Saturn`], ans:3, exp:`Saturn's rings, made mostly of ice and rock particles, are the largest and most visually striking ring system in the solar system.` },
      { q:`According to Kepler's first law, planets orbit the Sun in paths that are:`, ch:[`unpredictable, random curves`,`ellipses, with the Sun located at one focus`,`perfect circles`,`straight lines`], ans:1, exp:`Kepler's first law states that planetary orbits are ellipses, not perfect circles, with the Sun positioned at one of the two foci of the ellipse.` },
      { q:`According to Kepler's second law, a planet moves fastest in its orbit when it is:`, ch:[`always moving at a constant speed`,`farthest from the Sun (aphelion)`,`at exactly 90 degrees from the Sun`,`closest to the Sun (perihelion)`], ans:3, exp:`Kepler's second law (equal areas in equal times) means a planet speeds up as it nears the Sun and slows down as it moves farther away.` },
      { q:`The asteroid belt is located:`, ch:[`between Mars and Jupiter`,`between Mercury and Venus`,`between Earth and Mars only, close to Earth`,`beyond Neptune`], ans:0, exp:`The main asteroid belt lies between the orbits of Mars and Jupiter, containing millions of rocky remnants from the solar system's formation.` },
      { q:`Which planet rotates almost completely on its side, with an axial tilt of about 98 degrees?`, ch:[`Neptune`,`Uranus`,`Mercury`,`Saturn`], ans:1, exp:`Uranus has an unusually extreme axial tilt of about 98 degrees, meaning it essentially rolls around the Sun on its side.` },
      { q:`A "year" on a planet is defined as:`, ch:[`the time from sunrise to sunset`,`one full orbit around the Sun`,`one full rotation on its own axis`,`one full lunar cycle`], ans:1, exp:`A planetary year is the time it takes the planet to complete one full trip around the Sun.` },
      { q:`A "day" on a planet is defined as:`, ch:[`one full rotation on its own axis`,`one full year`,`one full orbit around the Sun`,`the time between eclipses`], ans:0, exp:`A day is the time it takes a planet to complete one full rotation on its own axis.` },
      { q:`Which group below lists only terrestrial (rocky) planets?`, ch:[`All eight planets equally`,`Jupiter, Saturn, Uranus, Neptune`,`Earth, Mars, Jupiter, Saturn`,`Mercury, Venus, Earth, Mars`], ans:3, exp:`The four inner, rocky planets — Mercury, Venus, Earth, and Mars — are classified as terrestrial planets.` },
      { q:`Which group below lists only gas giant planets?`, ch:[`Earth, Mars, Jupiter, Saturn`,`Mercury, Venus, Earth, Mars`,`Jupiter, Saturn, Uranus, Neptune`,`Only Jupiter and Saturn`], ans:2, exp:`Jupiter, Saturn, Uranus, and Neptune are the four outer gas/ice giant planets, all much larger and less dense than the terrestrial planets.` },
      { q:`Pluto is now officially classified as a:`, ch:[`moon of Neptune`,`asteroid`,`dwarf planet`,`full planet`], ans:2, exp:`In 2006, the International Astronomical Union reclassified Pluto as a dwarf planet because it does not clear its orbital neighborhood of other debris.` },
      { q:`The Sun is classified as a:`, ch:[`comet`,`star`,`planet`,`moon`], ans:1, exp:`The Sun is a star, a massive ball of hydrogen and helium powered by nuclear fusion, at the center of our solar system.` },
    ]
  },
  {
    id:'cp121', cat:'Physical Sciences', title:'Stars & Stellar Life Cycles', diff:'Easy',
    qs:[
      { q:`Stars generate energy primarily through:`, ch:[`chemical combustion`,`nuclear fusion of hydrogen into helium`,`gravitational collapse alone`,`radioactive decay alone`], ans:1, exp:`Stars shine because nuclear fusion in their cores converts hydrogen into helium, releasing enormous amounts of energy.` },
      { q:`Our Sun is currently in which stage of its life cycle?`, ch:[`Supernova remnant`,`Red giant`,`White dwarf`,`Main sequence`], ans:3, exp:`The Sun is a main sequence star, steadily fusing hydrogen into helium in its core, a stage it has been in for about 4.6 billion years.` },
      { q:`A star's color is primarily an indicator of its:`, ch:[`distance from Earth`,`surface temperature`,`age exclusively, unrelated to temperature`,`mass only, unrelated to temperature`], ans:1, exp:`A star's color reflects its surface temperature: hotter stars appear blue or white, while cooler stars appear orange or red.` },
      { q:`Blue stars are generally:`, ch:[`hotter than red stars`,`the same temperature as red stars`,`cooler than red stars`,`not real stars, just an optical illusion`], ans:0, exp:`Blue stars have much higher surface temperatures than red stars; temperature, not just distance, determines a star's apparent color.` },
      { q:`When a star like our Sun exhausts the hydrogen fuel in its core, it will expand into a:`, ch:[`black hole`,`white dwarf`,`red giant`,`neutron star`], ans:2, exp:`As core hydrogen runs out, the star's core contracts and heats up while its outer layers expand and cool, forming a red giant.` },
      { q:`After the red giant stage, a Sun-like star sheds its outer layers, leaving behind a hot, dense core called a:`, ch:[`black hole`,`white dwarf`,`red supergiant`,`neutron star`], ans:1, exp:`Stars with masses similar to the Sun end their lives as white dwarfs, dense, Earth-sized remnants that gradually cool over billions of years.` },
      { q:`Massive stars, much larger than the Sun, end their lives in a dramatic explosion called a:`, ch:[`comet`,`solar flare`,`nova`,`supernova`], ans:3, exp:`When a massive star's core collapses, it triggers a supernova, an extremely energetic explosion that can briefly outshine an entire galaxy.` },
      { q:`Following a supernova, the collapsed core of an extremely massive star may become a:`, ch:[`red dwarf`,`black hole`,`asteroid`,`white dwarf`], ans:1, exp:`If the remaining core mass is large enough, gravity overwhelms all other forces and the core collapses into a black hole.` },
      { q:`A neutron star is an extremely dense stellar remnant primarily composed of:`, ch:[`tightly packed neutrons`,`liquid helium`,`pure iron only`,`hydrogen gas`], ans:0, exp:`Neutron stars form when a massive star's core collapses so intensely that protons and electrons combine into neutrons, packing roughly a Sun's worth of mass into a city-sized sphere.` },
      { q:`The Hertzsprung-Russell (H-R) diagram plots stars according to their:`, ch:[`color versus chemical composition`,`luminosity (brightness) versus surface temperature`,`mass versus radius`,`distance versus age`], ans:1, exp:`The H-R diagram is a foundational tool in astronomy that plots stellar luminosity against temperature, revealing patterns like the main sequence.` },
      { q:`A star's main sequence lifetime is primarily determined by its:`, ch:[`distance from Earth`,`mass, since more massive stars burn through fuel much faster and live shorter lives`,`number of orbiting planets`,`color alone, independent of any other property`], ans:1, exp:`Paradoxically, more massive stars have more fuel but burn it far more rapidly due to higher core pressures and temperatures, giving them much shorter overall lifespans than smaller stars.` },
      { q:`Nuclear fusion in the core of a typical star converts hydrogen into:`, ch:[`helium`,`nitrogen`,`oxygen`,`carbon dioxide`], ans:0, exp:`The primary fusion process in most stars, including the Sun, combines hydrogen nuclei to form helium.` },
      { q:`A nebula is best described as:`, ch:[`a cloud of gas and dust, often a stellar nursery where new stars form`,`the boundary of a black hole`,`a type of rocky planet`,`a dead star`], ans:0, exp:`Nebulae are vast clouds of gas and dust in space; some are the birthplaces of new stars, while others form from the remnants of dying stars.` },
      { q:`The smallest, coolest, and most common type of main sequence star in the universe is a:`, ch:[`red dwarf`,`neutron star`,`white dwarf`,`blue giant`], ans:0, exp:`Red dwarfs are relatively small, cool, and dim stars, but they make up the vast majority of stars in the universe due to their long lifespans and ease of formation.` },
    ]
  },
  {
    id:'cp122', cat:'Physical Sciences', title:'The Moon, Phases & Tides', diff:'Easy',
    qs:[
      { q:`The Moon produces no light of its own; it is visible from Earth mainly because it:`, ch:[`glows due to internal heat`,`generates its own light through internal fusion`,`absorbs starlight and re-emits it`,`reflects sunlight off its surface`], ans:3, exp:`The Moon has no internal light source; it appears bright because its surface reflects sunlight back toward Earth.` },
      { q:`The changing phases of the Moon are caused by:`, ch:[`changing angles between the Sun, Moon, and Earth as the Moon orbits`,`the Moon physically changing shape`,`Earth's shadow gradually covering the Moon`,`clouds periodically blocking our view of the Moon`], ans:0, exp:`As the Moon orbits Earth, the portion of its sunlit half visible from Earth changes, producing the cycle of phases.` },
      { q:`A "new moon" occurs when:`, ch:[`the Moon appears completely full`,`the Moon is directly opposite the Sun from Earth`,`a lunar eclipse is always occurring`,`the Moon lies between Earth and the Sun, with its unlit side facing us`], ans:3, exp:`During a new moon, the Moon is roughly between Earth and the Sun, so the side facing Earth is unlit and the Moon is essentially invisible.` },
      { q:`A "full moon" occurs when:`, ch:[`the Moon lies between Earth and the Sun`,`the Moon becomes invisible`,`the Moon is always at its closest point to Earth`,`Earth lies roughly between the Sun and the Moon, so the Moon's lit side faces Earth`], ans:3, exp:`At full moon, Earth is roughly between the Sun and Moon, so we see the Moon's entire illuminated hemisphere.` },
      { q:`The Moon completes one full orbit around Earth (and one phase cycle) in approximately:`, ch:[`1 week`,`1 year`,`1 day`,`about 29.5 days`], ans:3, exp:`The Moon's synodic period, the time between successive full moons (or new moons), is about 29.5 days.` },
      { q:`Ocean tides are primarily caused by:`, ch:[`ocean currents circulating heat`,`Earth's rotation alone`,`the gravitational pull of the Moon, with a smaller contribution from the Sun`,`wind patterns over the ocean`], ans:2, exp:`The Moon's gravity pulls on Earth's oceans, creating bulges of water that produce high tides, with the Sun's gravity contributing a smaller secondary effect.` },
      { q:`Spring tides, with the highest high tides and lowest low tides, occur when:`, ch:[`the Sun, Earth, and Moon form a right angle`,`it happens to be springtime in that hemisphere`,`the Moon is at its farthest point from Earth`,`the Sun, Earth, and Moon are aligned, as at new or full moon`], ans:3, exp:`When the Sun and Moon are aligned with Earth (new or full moon), their gravitational effects combine, producing especially strong spring tides.` },
      { q:`Neap tides, with a smaller tidal range, occur when:`, ch:[`a lunar eclipse is occurring`,`the Sun and Moon are at roughly right angles relative to Earth, as at first or third quarter moon`,`the Sun and Moon are aligned`,`the Moon is full`], ans:1, exp:`When the Sun and Moon pull at right angles to each other, their tidal effects partially cancel, producing smaller neap tides.` },
      { q:`A solar eclipse occurs when:`, ch:[`the Moon passes between the Sun and Earth, blocking sunlight`,`the Sun permanently goes dark`,`Earth passes between the Sun and the Moon`,`the Moon enters Earth's shadow`], ans:0, exp:`A solar eclipse happens when the Moon's disk passes in front of the Sun as seen from Earth, temporarily blocking sunlight in the area of the Moon's shadow.` },
      { q:`A lunar eclipse occurs when:`, ch:[`the Sun blocks the Moon directly`,`the Moon passes between the Sun and Earth`,`the Moon simply disappears from the sky`,`Earth passes between the Sun and the Moon, casting its shadow on the Moon`], ans:3, exp:`A lunar eclipse occurs when Earth is positioned between the Sun and the Moon, so Earth's shadow falls across the Moon's surface.` },
      { q:`The Moon is gradually moving farther away from Earth over time due to:`, ch:[`solar wind pressure`,`tidal interactions that transfer angular momentum from Earth to the Moon`,`volcanic activity on the Moon`,`Earth's magnetic field`], ans:1, exp:`Tidal friction between Earth and the Moon gradually transfers angular momentum, causing the Moon's orbit to slowly expand over time (by a few centimeters per year).` },
      { q:`The same side of the Moon always faces Earth because:`, ch:[`Earth's gravity has stopped the Moon from rotating entirely`,`the Moon does not rotate on its axis at all`,`the Moon is much smaller than Earth`,`the Moon's rotation period exactly matches its orbital period, a state called tidal locking`], ans:3, exp:`Tidal locking causes the Moon to rotate on its axis in exactly the same time it takes to orbit Earth once, so the same hemisphere always faces us.` },
      { q:`How many major lunar phases are commonly identified across a full cycle (new, first quarter, full, third quarter, and the crescents/gibbous phases between them)?`, ch:[`Two`,`Four`,`Twelve`,`Eight`], ans:3, exp:`Astronomers typically describe eight distinct phases: new, waxing crescent, first quarter, waxing gibbous, full, waning gibbous, third quarter, and waning crescent.` },
      { q:`During a waxing phase, the illuminated portion of the Moon visible from Earth is:`, ch:[`growing each night`,`completely invisible`,`shrinking each night`,`staying exactly the same`], ans:0, exp:`"Waxing" describes the period when more of the Moon's near side becomes illuminated each night, building up toward a full moon.` },
    ]
  },
  {
    id:'cp123', cat:'Physical Sciences', title:'Plate Tectonics & Earthquakes', diff:'Easy',
    qs:[
      { q:`Earth's rigid outer shell is broken into large moving pieces called:`, ch:[`oceans`,`continents`,`tectonic plates`,`biomes`], ans:2, exp:`Earth's lithosphere is divided into several large and small tectonic plates that move slowly over the underlying mantle.` },
      { q:`Tectonic plates move primarily due to:`, ch:[`ocean tides`,`convection currents within the mantle`,`wind currents`,`magnetic reversals`], ans:1, exp:`Heat from Earth's interior drives slow convection currents in the mantle, which help push and drag the overlying tectonic plates.` },
      { q:`At a divergent plate boundary, plates:`, ch:[`collide and push together`,`slide past each other horizontally`,`remain completely stationary`,`move apart from one another`], ans:3, exp:`Divergent boundaries are where plates move apart, often allowing magma to rise and form new crust, as at mid-ocean ridges.` },
      { q:`At a convergent plate boundary, plates:`, ch:[`move apart from one another`,`collide, often forming mountains or subduction zones`,`slide past each other horizontally`,`stop moving permanently`], ans:1, exp:`Convergent boundaries occur where plates collide, which can build mountain ranges or force one plate to subduct beneath another.` },
      { q:`At a transform plate boundary, plates:`, ch:[`slide horizontally past one another`,`collide directly`,`move apart from one another`,`sink into the mantle`], ans:0, exp:`Transform boundaries occur where plates slide past each other horizontally, often generating significant earthquakes due to friction.` },
      { q:`The San Andreas Fault in California is a well-known example of a:`, ch:[`convergent boundary`,`transform boundary`,`hotspot`,`divergent boundary`], ans:1, exp:`The San Andreas Fault marks a transform boundary where the Pacific and North American plates slide horizontally past each other.` },
      { q:`The Mid-Atlantic Ridge is a well-known example of a:`, ch:[`subduction zone`,`convergent boundary`,`divergent boundary, where seafloor spreading occurs`,`transform boundary`], ans:2, exp:`The Mid-Atlantic Ridge is a divergent boundary where the Eurasian/African and American plates are moving apart, allowing new ocean floor to form.` },
      { q:`Subduction occurs when:`, ch:[`plates lock together and never move again`,`a denser oceanic plate sinks beneath a less dense plate at a convergent boundary`,`plates simply move apart from each other`,`two continental plates merge permanently into one`], ans:1, exp:`At many convergent boundaries, the denser oceanic plate is forced down (subducted) beneath the lighter plate, often generating volcanic activity and deep ocean trenches.` },
      { q:`Earthquakes are primarily caused by:`, ch:[`volcanic ash falling to the ground`,`ocean tides pulling on the crust`,`the sudden release of built-up stress along faults in Earth's crust`,`wind erosion of surface rocks`], ans:2, exp:`Stress gradually builds along fault lines as plates try to move; when the stress is suddenly released, the ground shakes, producing an earthquake.` },
      { q:`The point on Earth's surface directly above where an earthquake originates is called the:`, ch:[`focus`,`fault line`,`epicenter`,`seismograph`], ans:2, exp:`The epicenter is the surface location directly above the earthquake's underground point of origin.` },
      { q:`The point underground where an earthquake actually originates is called the:`, ch:[`fault plane`,`plate boundary`,`focus (or hypocenter)`,`epicenter`], ans:2, exp:`The focus (or hypocenter) is the actual underground location where the fault rupture and energy release begin.` },
      { q:`Seismographs detect and measure earthquakes by recording:`, ch:[`air pressure changes`,`magnetic field changes`,`temperature changes`,`ground vibrations, known as seismic waves`], ans:3, exp:`Seismographs measure the vibrations (seismic waves) that travel through the ground during an earthquake.` },
      { q:`The Richter scale and the moment magnitude scale are both used to measure:`, ch:[`wind speed`,`the size (energy release) of earthquakes`,`volcanic ash content`,`the depth of the ocean`], ans:1, exp:`Both scales quantify the amount of energy released by an earthquake, with each whole number step representing a much larger release of energy.` },
      { q:`Alfred Wegener's theory explaining the matching shapes of continents like South America and Africa is known as:`, ch:[`seafloor spreading`,`plate tectonics`,`continental drift`,`the rock cycle`], ans:2, exp:`Wegener proposed continental drift in the early 20th century, an idea later incorporated into the modern, more complete theory of plate tectonics.` },
    ]
  },
  {
    id:'cp124', cat:'Physical Sciences', title:'Volcanoes & Igneous Processes', diff:'Easy',
    qs:[
      { q:`Magma is molten rock located:`, ch:[`on Earth's surface`,`only inside actively erupting volcanoes`,`beneath Earth's surface`,`only within the ocean`], ans:2, exp:`Magma refers specifically to molten rock while it remains underground, beneath Earth's surface.` },
      { q:`Once magma reaches Earth's surface, it is instead called:`, ch:[`magma still`,`ash`,`lava`,`sediment`], ans:2, exp:`The same molten rock is renamed lava once it erupts and flows out onto Earth's surface.` },
      { q:`Igneous rocks form from the cooling and solidification of:`, ch:[`magma or lava`,`loose sediment`,`other rocks under extreme heat and pressure, without melting`,`organic material`], ans:0, exp:`Igneous rock forms whenever molten rock (magma below ground or lava at the surface) cools and crystallizes into a solid.` },
      { q:`Intrusive (plutonic) igneous rocks form when magma cools:`, ch:[`quickly at Earth's surface`,`only while submerged in ocean water`,`slowly, deep beneath Earth's surface`,`instantly in open air`], ans:2, exp:`Intrusive igneous rocks crystallize slowly underground, which allows large mineral crystals to form.` },
      { q:`Extrusive (volcanic) igneous rocks form when lava cools:`, ch:[`slowly, deep underground`,`quickly, at Earth's surface`,`only under laboratory conditions`,`over millions of years underground only`], ans:1, exp:`Extrusive rocks form when lava erupts and cools rapidly at the surface, leaving little time for large crystals to grow.` },
      { q:`Slow cooling of magma underground typically produces igneous rock with:`, ch:[`only microscopic or no crystals (a fine-grained texture)`,`only a glassy texture`,`no crystals at all`,`large, well-formed crystals`], ans:3, exp:`Slow cooling allows atoms plenty of time to arrange into large, visible mineral crystals, producing a coarse-grained texture.` },
      { q:`Rapid cooling of lava at Earth's surface typically produces igneous rock with:`, ch:[`no minerals of any kind`,`only sedimentary layering`,`a fine-grained or glassy texture, with small or no visible crystals`,`large crystals`], ans:2, exp:`Fast cooling doesn't give crystals much time to grow, resulting in very small crystals or, in extreme cases, a glassy texture with no crystal structure at all.` },
      { q:`Granite is a common example of a(n):`, ch:[`metamorphic rock`,`sedimentary rock`,`extrusive igneous rock`,`intrusive igneous rock`], ans:3, exp:`Granite forms from magma that cooled slowly underground, giving it large, visible mineral crystals typical of intrusive igneous rocks.` },
      { q:`Basalt is a common example of a(n):`, ch:[`extrusive igneous rock`,`intrusive igneous rock`,`sedimentary rock`,`metamorphic rock`], ans:0, exp:`Basalt forms from lava that cooled quickly at Earth's surface, giving it the fine-grained texture typical of extrusive igneous rocks.` },
      { q:`Shield volcanoes, like those found in Hawaii, are characterized by:`, ch:[`explosive eruptions of thick, gas-rich magma`,`having no lava at all`,`gentle eruptions of fluid, low-viscosity basaltic lava, forming broad, gently sloping mountains`,`being permanently extinct`], ans:2, exp:`Shield volcanoes are built up over time by many gentle, effusive eruptions of runny basaltic lava, producing a wide, gently sloped profile.` },
      { q:`Composite volcanoes (stratovolcanoes) are typically associated with:`, ch:[`gentle, effusive basaltic eruptions`,`only underwater volcanic activity`,`explosive eruptions of thick, viscous, gas-rich magma, often at convergent plate boundaries`,`having no eruptive activity at all`], ans:2, exp:`Stratovolcanoes form from thicker, more viscous magma that traps gas, leading to more explosive, dangerous eruptions; they commonly occur along convergent (subduction) boundaries.` },
      { q:`A "hotspot" volcano, such as those forming the Hawaiian Islands, is caused by:`, ch:[`a relatively stationary plume of magma rising from deep within the mantle`,`earthquakes alone`,`a plate boundary directly beneath it`,`a process entirely unrelated to Earth's interior`], ans:0, exp:`Hotspots are fixed magma plumes rising from deep in the mantle; as a tectonic plate moves over the stationary hotspot, it creates a chain of volcanic islands.` },
      { q:`Obsidian, a natural volcanic glass, forms because the lava that produced it cooled:`, ch:[`from sedimentary material`,`so slowly that large crystals had time to form`,`underground over millions of years`,`so quickly that no crystal structure had time to form`], ans:3, exp:`Obsidian forms when lava cools almost instantly, so fast that atoms have no chance to arrange into an organized crystal lattice, resulting in natural glass.` },
      { q:`Pyroclastic material, such as volcanic ash and pumice, forms through:`, ch:[`slow crystallization deep underground`,`explosive fragmentation of magma and rock during a violent eruption`,`sedimentary deposition over time`,`metamorphism under heat and pressure`], ans:1, exp:`Explosive eruptions violently shatter magma and surrounding rock into fine ash and porous fragments like pumice, which are collectively called pyroclastic material.` },
    ]
  },
  {
    id:'cp125', cat:'Physical Sciences', title:'Minerals & the Rock Cycle', diff:'Easy',
    qs:[
      { q:`A mineral is defined as a naturally occurring, inorganic solid with:`, ch:[`a liquid form at room temperature`,`a biological origin`,`a definite crystalline structure and a specific chemical composition`,`a random atomic arrangement and a variable chemical composition`], ans:2, exp:`Minerals are naturally occurring inorganic solids with an orderly, repeating crystal structure and a defined (or narrowly variable) chemical formula.` },
      { q:`The three main categories of rock are:`, ch:[`hard, soft, and liquid`,`igneous, sedimentary, and metamorphic`,`volcanic, plutonic, and organic`,`mineral, crystal, and glass`], ans:1, exp:`Geologists classify all rocks into igneous, sedimentary, or metamorphic categories, based on how they formed.` },
      { q:`Sedimentary rocks typically form through:`, ch:[`extreme heat and pressure altering an existing rock`,`the deposition, compaction, and cementation of sediment`,`the cooling of magma`,`direct volcanic eruption`], ans:1, exp:`Sedimentary rocks form as layers of sediment accumulate, become compressed, and are cemented together over time.` },
      { q:`Metamorphic rocks form when an existing rock is changed by:`, ch:[`weathering alone`,`intense heat and pressure, without fully melting`,`the cooling of lava`,`simply dissolving in water`], ans:1, exp:`Metamorphic rocks form when existing rock is transformed by heat and pressure deep within Earth's crust, without completely melting.` },
      { q:`Which of the following is an example of a sedimentary rock?`, ch:[`Basalt`,`Sandstone`,`Marble`,`Granite`], ans:1, exp:`Sandstone forms from compacted and cemented sand grains, making it a classic sedimentary rock; granite and basalt are igneous, and marble is metamorphic.` },
      { q:`Which of the following is an example of a metamorphic rock?`, ch:[`Obsidian`,`Limestone`,`Sandstone`,`Marble, formed by the metamorphism of limestone`], ans:3, exp:`Marble forms when limestone is subjected to heat and pressure, recrystallizing into a denser, metamorphic rock.` },
      { q:`The Mohs hardness scale is used to determine a mineral's:`, ch:[`density`,`crystal shape`,`color`,`resistance to being scratched`], ans:3, exp:`The Mohs scale ranks minerals from 1 (softest, like talc) to 10 (hardest, like diamond) based on their ability to resist scratching.` },
      { q:`A mineral's "streak" refers to:`, ch:[`the color of its powder when scraped across an unglazed porcelain tile`,`its overall luster`,`its crystal shape`,`the color of the mineral's outer surface`], ans:0, exp:`Streak is often more reliable than surface color for identifying a mineral, since it shows the true color of the mineral's powdered form.` },
      { q:`"Luster" describes how a mineral:`, ch:[`conducts electricity`,`reflects light from its surface`,`tastes when licked`,`reacts chemically with acid`], ans:1, exp:`Luster describes the way light reflects off a mineral's surface, such as metallic, glassy, pearly, or dull.` },
      { q:`The rock cycle describes how:`, ch:[`rocks can transform between igneous, sedimentary, and metamorphic types over long spans of geologic time`,`rocks are permanently fixed and never change form`,`only igneous rocks exist on Earth`,`minerals can only ever form once`], ans:0, exp:`The rock cycle illustrates the continuous, gradual transformation of rock material between the three major rock types through processes like melting, erosion, and metamorphism.` },
      { q:`Cleavage in minerals refers to:`, ch:[`the color of the mineral`,`the hardness of the mineral`,`its melting point`,`the tendency of a mineral to break along smooth, flat planes`], ans:3, exp:`Cleavage describes how a mineral's crystal structure causes it to break along particular flat planes of weakness, unlike fracture, which produces irregular breaks.` },
      { q:`Quartz is a common mineral composed primarily of:`, ch:[`calcium carbonate`,`pure carbon`,`silicon and oxygen (silicon dioxide)`,`iron oxide`], ans:2, exp:`Quartz is made of silicon dioxide (SiO2) and is one of the most abundant minerals in Earth's crust.` },
      { q:`If sedimentary rock is subjected to intense heat and pressure without fully melting, it can become:`, ch:[`a new mineral only, never a rock`,`magma`,`metamorphic rock`,`igneous rock`], ans:2, exp:`Existing rock transformed by heat and pressure (without melting) becomes metamorphic rock, regardless of what type of rock it started as.` },
      { q:`If any type of rock completely melts and then cools and solidifies, it forms:`, ch:[`sedimentary rock`,`a mineral only`,`igneous rock`,`metamorphic rock`], ans:2, exp:`Complete melting followed by cooling and solidification always produces igneous rock, regardless of the original rock type.` },
    ]
  },
  {
    id:'cp126', cat:'Physical Sciences', title:'Weather Systems & Fronts', diff:'Easy',
    qs:[
      { q:`A weather front is best described as:`, ch:[`a boundary found only at the equator`,`the same thing as a tornado`,`the boundary between two air masses with different temperature and/or humidity characteristics`,`a permanent boundary that never moves`], ans:2, exp:`A front marks the transition zone where two air masses of differing temperature and humidity meet, often triggering changes in weather.` },
      { q:`A cold front occurs when:`, ch:[`a cold air mass actively displaces a warmer air mass, pushing it upward quickly`,`two air masses of identical temperature meet`,`a warm air mass slowly overtakes a cooler air mass`,`atmospheric pressure remains perfectly constant`], ans:0, exp:`Cold fronts form when denser cold air pushes forcefully under and lifts a warmer air mass, often producing rapid, intense weather changes.` },
      { q:`A warm front occurs when:`, ch:[`pressure suddenly spikes with no other cause`,`no air masses are involved at all`,`cold air quickly displaces warm air`,`a warm air mass advances and gradually rises over a retreating cold air mass`], ans:3, exp:`Warm fronts form as warm air slowly overrides a mass of cooler, denser air, typically producing gradual, longer-lasting precipitation.` },
      { q:`Cold fronts are generally associated with:`, ch:[`long, gentle rain lasting for days`,`no change in weather at all`,`only clear skies, with no precipitation`,`sudden, intense storms often followed by clearer skies`], ans:3, exp:`The rapid lifting of warm air along a cold front often produces short, intense storms, which are typically followed by cooler, clearer conditions.` },
      { q:`Warm fronts are generally associated with:`, ch:[`only snow, regardless of season`,`no precipitation whatsoever`,`sudden, violent thunderstorms`,`gradual, prolonged light-to-moderate precipitation`], ans:3, exp:`Because warm air rises slowly and gradually over a warm front, precipitation tends to be lighter but more prolonged compared to a cold front.` },
      { q:`An occluded front forms when:`, ch:[`two warm fronts collide directly`,`no fronts are present in the area`,`a fast-moving cold front catches up to and overtakes a warm front`,`atmospheric pressure becomes completely equalized`], ans:2, exp:`An occluded front develops when a cold front catches up with a warm front, lifting the warm air mass entirely off the ground between two cooler air masses.` },
      { q:`Low-pressure weather systems are generally associated with:`, ch:[`no noticeable weather effects at all`,`sinking air and consistently clear skies`,`clear, calm weather with sinking air`,`rising air, cloud formation, and precipitation`], ans:3, exp:`Low-pressure areas are characterized by rising air, which cools and condenses to form clouds and precipitation.` },
      { q:`High-pressure weather systems are generally associated with:`, ch:[`sinking air and generally clear, calm conditions`,`tornado formation`,`constant, heavy rain`,`stormy, unsettled weather`], ans:0, exp:`High-pressure systems feature sinking air, which tends to suppress cloud formation and produce clear, calm weather.` },
      { q:`In the Northern Hemisphere, winds circulating around a low-pressure system typically rotate:`, ch:[`clockwise`,`counterclockwise`,`they do not rotate at all`,`in a random, unpredictable direction`], ans:1, exp:`Due to the Coriolis effect, winds around low-pressure systems rotate counterclockwise in the Northern Hemisphere (and clockwise in the Southern Hemisphere).` },
      { q:`A stationary front occurs when:`, ch:[`only cold air is present in the area`,`atmospheric pressure drops to zero`,`two air masses meet but neither advances significantly`,`the front moves very quickly across a region`], ans:2, exp:`A stationary front forms when two air masses meet without either one able to displace the other, often leading to prolonged periods of unsettled weather in one area.` },
      { q:`Isobars on a weather map are lines connecting points of equal:`, ch:[`atmospheric pressure`,`humidity`,`wind speed`,`temperature`], ans:0, exp:`Isobars connect locations that share the same atmospheric pressure, helping meteorologists visualize pressure systems and predict wind patterns.` },
      { q:`Meteorologists use fronts, isobars, and air masses primarily to:`, ch:[`measure ocean depth`,`predict earthquakes`,`track volcanic eruptions`,`forecast upcoming weather patterns`], ans:3, exp:`Tracking fronts, pressure patterns, and air masses is central to forecasting how weather will develop and change over the coming days.` },
      { q:`Thunderstorms often develop along which type of front, due to the rapid lifting of warm, moist air?`, ch:[`Stationary fronts only`,`High-pressure ridges`,`Calm zones with no fronts present`,`Cold fronts`], ans:3, exp:`The abrupt lifting of warm, moist air ahead of an advancing cold front frequently triggers strong, sometimes severe, thunderstorms.` },
      { q:`The jet stream influences weather primarily by:`, ch:[`remaining perfectly still at all times`,`steering weather systems and air masses across large distances at high altitude`,`directly causing earthquakes`,`only affecting deep ocean currents`], ans:1, exp:`The jet stream is a fast-moving band of air high in the atmosphere that steers the movement of storms and air masses across continents.` },
    ]
  },
  {
    id:'cp127', cat:'Physical Sciences', title:'The Water Cycle & Ocean Basics', diff:'Easy',
    qs:[
      { q:`Evaporation is the process by which:`, ch:[`water falls to the ground as precipitation`,`ice turns directly into vapor`,`water vapor turns into liquid water`,`liquid water turns into water vapor`], ans:3, exp:`Evaporation occurs when liquid water absorbs energy (often from the Sun) and transitions into water vapor gas.` },
      { q:`Condensation is the process by which:`, ch:[`water falls to Earth's surface as rain`,`ice melts into liquid water`,`liquid water evaporates into vapor`,`water vapor cools and turns into tiny liquid droplets, forming clouds`], ans:3, exp:`As rising water vapor cools, it condenses into tiny liquid droplets that cluster together to form clouds.` },
      { q:`Precipitation refers to:`, ch:[`water falling from the atmosphere to Earth's surface as rain, snow, sleet, or hail`,`water evaporating from oceans`,`water freezing while still inside clouds`,`water flowing underground`], ans:0, exp:`Precipitation is any form of water, liquid or solid, that falls from clouds to Earth's surface.` },
      { q:`Transpiration is the process by which:`, ch:[`rocks are broken down by weathering`,`rivers are formed`,`plants release water vapor into the atmosphere through their leaves`,`animals release water through sweating`], ans:2, exp:`Transpiration is the release of water vapor from plant leaves, which contributes significantly to the water cycle alongside evaporation from open water surfaces.` },
      { q:`Runoff refers to water that:`, ch:[`is entirely absorbed by plant roots`,`flows over land into streams, rivers, and eventually larger bodies of water`,`condenses directly into clouds`,`evaporates directly from the ocean surface`], ans:1, exp:`Runoff is precipitation that flows across the land surface rather than soaking into the ground, eventually draining into streams and rivers.` },
      { q:`Infiltration refers to water that:`, ch:[`falls only as snow`,`flows over the surface as runoff`,`evaporates immediately upon reaching the ground`,`seeps into the ground and becomes groundwater`], ans:3, exp:`Infiltration is the process by which surface water percolates down into the soil and rock layers below, replenishing groundwater supplies.` },
      { q:`The vast majority of Earth's water is found in the:`, ch:[`lakes`,`rivers`,`atmosphere`,`oceans`], ans:3, exp:`Oceans hold roughly 97% of all water on Earth, making them by far the largest reservoir in the water cycle.` },
      { q:`Approximately what percentage of Earth's surface is covered by ocean?`, ch:[`About 50%`,`About 90%`,`About 71%`,`About 30%`], ans:2, exp:`Oceans cover roughly 71% of Earth's surface, making Earth appropriately known as the "blue planet."` },
      { q:`The energy that drives the water cycle primarily comes from:`, ch:[`the Sun`,`geothermal heat from Earth's core`,`ocean currents themselves`,`the Moon's gravitational pull`], ans:0, exp:`Solar energy powers evaporation from oceans and other surfaces, providing the driving force for the entire water cycle.` },
      { q:`Groundwater is stored in underground layers of rock and sediment called:`, ch:[`estuaries`,`deltas`,`glaciers`,`aquifers`], ans:3, exp:`Aquifers are permeable underground layers of rock, sand, or gravel that can hold and transmit significant amounts of groundwater.` },
      { q:`Salinity of ocean water refers to:`, ch:[`its density alone, unrelated to dissolved substances`,`the concentration of dissolved salts in the water`,`its temperature`,`its color`], ans:1, exp:`Salinity measures how much dissolved salt (mostly sodium chloride) is present in a body of water.` },
      { q:`Ocean currents are driven in part by differences in water temperature and salinity, in a process known as:`, ch:[`the water cycle`,`thermohaline circulation`,`transpiration`,`infiltration`], ans:1, exp:`Thermohaline circulation is the large-scale ocean circulation driven by density differences caused by variations in temperature ("thermo") and salinity ("haline").` },
      { q:`A watershed (drainage basin) is best described as:`, ch:[`an area of land that drains into a particular river, lake, or ocean`,`a large ocean wave`,`an underground cave system`,`a specific type of cloud`], ans:0, exp:`A watershed is the entire land area whose surface runoff and streams all eventually feed into a common body of water.` },
      { q:`Most of Earth's freshwater (excluding oceans) is stored as:`, ch:[`water vapor in the atmosphere`,`liquid water in rivers`,`groundwater exclusively`,`ice in glaciers and polar ice caps`], ans:3, exp:`The majority of Earth's freshwater is locked up as ice in glaciers and ice caps, with groundwater making up most of the remaining liquid freshwater.` },
    ]
  },
  {
    id:'cp128', cat:'Physical Sciences', title:'Climate Zones & Biomes', diff:'Easy',
    qs:[
      { q:`Climate is best described as:`, ch:[`the temperature recorded on any one given day`,`the long-term average weather pattern of a region`,`the day-to-day condition of the atmosphere`,`a single storm event`], ans:1, exp:`Climate describes the typical, long-term weather patterns of a region observed over many years, unlike weather, which describes short-term conditions.` },
      { q:`Weather differs from climate in that weather describes:`, ch:[`only long-term temperature trends`,`short-term atmospheric conditions at a given day or moment`,`long-term averages over decades`,`only seasonal precipitation totals`], ans:1, exp:`Weather refers to the atmospheric conditions at a specific place and time, such as today's temperature or an approaching storm.` },
      { q:`Regions near the equator generally have which climate characteristic?`, ch:[`Cold temperatures year-round`,`No precipitation at any time of year`,`Extreme seasonal temperature swings`,`Warm temperatures with intense, direct solar energy input year-round`], ans:3, exp:`The equator receives the most direct sunlight throughout the year, keeping temperatures warm with relatively little seasonal variation.` },
      { q:`Polar climate zones are characterized by:`, ch:[`desert conditions with intense heat`,`very high average temperatures`,`dense rainforest vegetation`,`very low average temperatures and minimal solar energy input`], ans:3, exp:`Polar regions receive sunlight at a low, indirect angle and for much of the year experience extended darkness, resulting in very cold average temperatures.` },
      { q:`A desert biome is primarily defined by:`, ch:[`dense forest cover`,`constant snowfall`,`consistently high humidity year-round`,`low precipitation, regardless of temperature`], ans:3, exp:`Deserts are classified based on very low annual precipitation; they can be hot (like the Sahara) or cold (like parts of Antarctica).` },
      { q:`Tropical rainforest biomes are characterized by:`, ch:[`high precipitation, warm temperatures, and high biodiversity`,`low precipitation and low biodiversity`,`sparse vegetation cover`,`freezing temperatures year-round`], ans:0, exp:`Tropical rainforests receive abundant rainfall and consistently warm temperatures, supporting some of the highest levels of biodiversity on Earth.` },
      { q:`Tundra biomes are characterized by:`, ch:[`hot temperatures and lush vegetation`,`cold temperatures, permafrost, and low-growing vegetation`,`tropical rainfall patterns`,`dense rainforest canopy cover`], ans:1, exp:`Tundra regions have very cold climates with a layer of permanently frozen subsoil (permafrost), supporting only low-growing plants like mosses and shrubs.` },
      { q:`Latitude affects a region's climate primarily by influencing:`, ch:[`ocean salinity levels`,`the rock cycle`,`volcanic activity`,`the angle and intensity of incoming solar radiation`], ans:3, exp:`Latitude determines how directly sunlight strikes a region, with areas near the equator receiving more direct, intense solar energy than polar regions.` },
      { q:`Altitude (elevation) affects local climate because:`, ch:[`elevation has essentially no effect on temperature`,`only latitude affects temperature, not elevation`,`higher elevations are generally warmer`,`higher elevations are generally cooler, as the atmosphere thins`], ans:3, exp:`Air temperature typically decreases with increasing altitude, which is why mountain peaks can be snow-capped even in warm, low-latitude regions.` },
      { q:`Ocean currents can affect regional climate by:`, ch:[`blocking incoming sunlight entirely`,`transporting warm or cold water that moderates the temperature of nearby coastal regions`,`only affecting local fish populations`,`having no thermal effect on nearby land`], ans:1, exp:`Ocean currents carry heat around the globe; warm currents can moderate winters in coastal areas, while cold currents can keep nearby regions cooler than expected.` },
      { q:`A temperate climate zone, like much of the continental United States, typically experiences:`, ch:[`no distinct seasons at all`,`four distinct seasons with moderate temperature variation`,`constant, extreme heat year-round`,`constant, extreme cold year-round`], ans:1, exp:`Temperate zones, located between the tropics and polar regions, typically experience four relatively distinct seasons with moderate temperature swings.` },
      { q:`Which factor does NOT typically influence a region's climate?`, ch:[`Nearby ocean currents`,`The current phase of the Moon`,`Latitude`,`Elevation`], ans:1, exp:`The Moon's phase has no meaningful effect on regional climate; latitude, elevation, and ocean currents are all major climate-shaping factors.` },
      { q:`Rain shadow deserts tend to form on the:`, ch:[`ocean floor`,`equator exclusively`,`leeward (dry) side of a mountain range, after moist air has released its precipitation`,`windward (wet) side of a mountain range`], ans:2, exp:`As moist air rises and cools on the windward side of a mountain, it releases most of its moisture; the descending, dried-out air on the leeward side creates a rain shadow desert.` },
      { q:`The Koppen climate classification system organizes climates primarily based on:`, ch:[`population density`,`political boundaries`,`ocean depth`,`temperature and precipitation patterns`], ans:3, exp:`The widely used Koppen system classifies world climates according to characteristic patterns of temperature and precipitation throughout the year.` },
    ]
  },
  {
    id:'cp129', cat:'Physical Sciences', title:'Environmental Chemistry: Pollution & Acid Rain', diff:'Medium',
    qs:[
      { q:`Acid rain is primarily caused by atmospheric reactions involving:`, ch:[`argon and helium`,`carbon dioxide and water vapor only`,`oxygen and nitrogen gas`,`sulfur dioxide (SO2) and nitrogen oxides (NOx) reacting with water vapor`], ans:3, exp:`SO2 and NOx, largely released from burning fossil fuels, react with atmospheric water to form sulfuric and nitric acids, which fall as acid rain.` },
      { q:`Normal, unpolluted rainwater is naturally slightly acidic (pH around 5.6) mainly due to dissolved:`, ch:[`sulfuric acid`,`hydrochloric acid`,`nitric acid`,`carbon dioxide, which forms carbonic acid`], ans:3, exp:`Atmospheric CO2 dissolves in rainwater to form weak carbonic acid, giving even unpolluted rain a slightly acidic pH.` },
      { q:`Acid rain can damage ecosystems by:`, ch:[`increasing biodiversity in affected areas`,`lowering the pH of soil and water bodies, harming aquatic life and vegetation`,`raising the pH of soil and water excessively`,`having no measurable environmental effects`], ans:1, exp:`Acid rain lowers the pH of lakes, streams, and soils, which can harm fish and other aquatic organisms and damage plant and forest health.` },
      { q:`A major source of sulfur dioxide emissions that contributes to acid rain is:`, ch:[`dormant (non-erupting) volcanoes`,`evaporation from the ocean`,`burning fossil fuels, especially coal, in power plants`,`photosynthesis by plants`], ans:2, exp:`Coal often contains sulfur impurities, which are released as sulfur dioxide when the coal is burned for electricity generation.` },
      { q:`Which of the following best describes eutrophication?`, ch:[`Depletion of the stratospheric ozone layer`,`The formation of acid rain`,`Excess nutrients, like nitrogen and phosphorus, causing algal blooms and oxygen depletion in water bodies`,`A global decrease in average temperature`], ans:2, exp:`Eutrophication occurs when runoff carrying excess nutrients (often from fertilizer) fuels explosive algae growth; when the algae die and decompose, oxygen levels drop sharply, harming aquatic life.` },
      { q:`The ozone layer in the stratosphere primarily protects life on Earth by:`, ch:[`producing breathable oxygen for organisms`,`causing acid rain to form`,`absorbing most of the harmful ultraviolet (UV) radiation from the Sun`,`trapping heat like a greenhouse gas`], ans:2, exp:`Stratospheric ozone absorbs the majority of incoming UV radiation, shielding living organisms from its damaging effects.` },
      { q:`Chlorofluorocarbons (CFCs), once common in aerosols and refrigerants, contributed to which environmental problem?`, ch:[`Depletion of the stratospheric ozone layer`,`Acid rain`,`Ocean acidification`,`Eutrophication of lakes`], ans:0, exp:`CFC molecules released ozone-destroying chlorine atoms into the stratosphere, significantly thinning the ozone layer, most notably over Antarctica.` },
      { q:`Ocean acidification is primarily driven by the ocean absorbing excess atmospheric:`, ch:[`methane`,`oxygen`,`nitrogen`,`carbon dioxide, which forms carbonic acid in seawater`], ans:3, exp:`As oceans absorb rising levels of atmospheric CO2, it reacts with seawater to form carbonic acid, gradually lowering ocean pH.` },
      { q:`Particulate matter air pollution primarily comes from:`, ch:[`plant photosynthesis`,`ocean spray exclusively`,`combustion sources, such as vehicle exhaust and industrial processes`,`only natural volcanic sources`], ans:2, exp:`Burning fuels in vehicles, factories, and power plants releases fine particulate matter, a major contributor to urban air pollution.` },
      { q:`Which gas is a primary contributor to smog formation in urban areas?`, ch:[`Helium`,`Nitrogen gas`,`Argon`,`Ground-level ozone, formed from reactions involving NOx and volatile organic compounds`], ans:3, exp:`Sunlight-driven reactions between nitrogen oxides and volatile organic compounds produce ground-level ozone, a key component of urban smog.` },
      { q:`Acid rain can chemically corrode which type of structures over time?`, ch:[`Only glass structures`,`Only wooden structures`,`Only plastic materials`,`Limestone and marble buildings and monuments`], ans:3, exp:`Acid rain reacts with and dissolves calcium carbonate, gradually eroding limestone and marble buildings, statues, and monuments.` },
      { q:`Bioaccumulation refers to:`, ch:[`the gradual buildup of substances, like mercury, within an organism's tissues over time`,`pollutants being immediately and harmlessly broken down`,`a process that only affects plants, not animals`,`the natural cycling of nutrients through an ecosystem`], ans:0, exp:`Bioaccumulation occurs when an organism absorbs a substance faster than it can eliminate it, causing that substance to build up in its tissues over its lifetime.` },
      { q:`Biomagnification describes how pollutant concentrations tend to:`, ch:[`increase at higher trophic levels within a food chain`,`decrease at higher trophic levels`,`only ever occur in primary producers`,`remain constant across all trophic levels`], ans:0, exp:`As predators consume many prey organisms, pollutants like mercury accumulated in those prey become increasingly concentrated at each successive trophic level.` },
      { q:`Liming (adding crushed limestone) is sometimes used to treat lakes damaged by acid rain because it:`, ch:[`increases the water's acidity further`,`has no meaningful chemical effect on the water`,`removes all dissolved oxygen from the lake`,`neutralizes excess acidity by raising the water's pH`], ans:3, exp:`Limestone is a base that reacts with and neutralizes excess acid in the water, helping restore a more normal pH for aquatic life.` },
    ]
  },
  {
    id:'cp130', cat:'Physical Sciences', title:'The Greenhouse Effect & Global Warming', diff:'Medium',
    qs:[
      { q:`The greenhouse effect refers to:`, ch:[`the cooling of Earth's atmosphere by reflecting all incoming sunlight`,`a growing hole in the ozone layer`,`the process of photosynthesis in plants`,`the trapping of heat within Earth's atmosphere by certain gases, keeping the planet warm enough to support life`], ans:3, exp:`Greenhouse gases absorb and re-radiate infrared heat, trapping warmth in the atmosphere and keeping Earth's average temperature habitable.` },
      { q:`Which gas is generally considered the most significant greenhouse gas contributing to human-driven (enhanced) warming?`, ch:[`Carbon dioxide`,`Nitrogen`,`Oxygen`,`Argon`], ans:0, exp:`Carbon dioxide, released largely by burning fossil fuels, is the primary greenhouse gas driving the recent enhancement of the greenhouse effect.` },
      { q:`Greenhouse gases warm the atmosphere mainly by:`, ch:[`blocking all incoming sunlight from reaching the surface`,`directly cooling Earth's surface`,`absorbing and re-emitting infrared radiation (heat) that would otherwise escape into space`,`reflecting ultraviolet radiation back into space`], ans:2, exp:`Greenhouse gas molecules absorb outgoing infrared radiation from Earth's surface and re-radiate some of it back downward, trapping heat in the lower atmosphere.` },
      { q:`Without any greenhouse effect at all, Earth's average surface temperature would be:`, ch:[`unpredictable, but unrelated to atmospheric composition`,`exactly the same as today`,`much colder than it is today, likely below freezing`,`much warmer than it is today`], ans:2, exp:`The natural greenhouse effect keeps Earth roughly 33 degrees Celsius warmer than it would otherwise be, so without it, Earth would be far too cold to support most life.` },
      { q:`Which of the following is a significant greenhouse gas besides carbon dioxide?`, ch:[`Argon (Ar)`,`Methane (CH4)`,`Oxygen (O2)`,`Nitrogen (N2)`], ans:1, exp:`Methane is a potent greenhouse gas, released from sources like livestock, landfills, and natural gas leaks; nitrogen, oxygen, and argon are not significant greenhouse gases.` },
      { q:`The primary human activity responsible for rising atmospheric CO2 levels since the Industrial Revolution is:`, ch:[`ocean evaporation`,`deforestation alone`,`volcanic eruptions`,`the burning of fossil fuels, such as coal, oil, and natural gas`], ans:3, exp:`Burning fossil fuels for energy and transportation is the largest single source of the CO2 increase observed since the Industrial Revolution.` },
      { q:`Deforestation contributes to rising atmospheric CO2 levels because:`, ch:[`it has essentially no effect on atmospheric carbon levels`,`trees constantly emit CO2 on their own`,`fewer trees means less CO2 is removed from the atmosphere via photosynthesis`,`forests directly produce greenhouse gases through decay`], ans:2, exp:`Forests act as carbon sinks, absorbing CO2 through photosynthesis; removing large numbers of trees reduces this natural carbon removal and can release stored carbon as well.` },
      { q:`Global warming specifically refers to:`, ch:[`normal seasonal temperature changes`,`the long-term rise in Earth's average surface temperature`,`the cooling of polar ice caps`,`the daily temperature swing between morning and night`], ans:1, exp:`Global warming describes the sustained, long-term increase in Earth's average surface temperature, primarily linked to rising greenhouse gas concentrations.` },
      { q:`One well-documented consequence of global warming is:`, ch:[`rising global sea levels, due to thermal expansion of seawater and melting ice`,`expanding polar ice sheets`,`decreasing average ocean temperatures`,`decreasing atmospheric CO2 concentrations`], ans:0, exp:`As ocean water warms, it expands, and melting glaciers and ice sheets add more water to the ocean — both processes are contributing to observed sea level rise.` },
      { q:`The Keeling Curve is a well-known graph that tracks:`, ch:[`ozone layer thickness`,`atmospheric carbon dioxide concentration over time`,`sea level changes since 1950`,`global average temperatures since 1900`], ans:1, exp:`The Keeling Curve, based on measurements begun at Mauna Loa Observatory in 1958, shows the steady rise (with seasonal fluctuations) in atmospheric CO2 concentration.` },
      { q:`Positive feedback loops in the climate system, such as melting ice reducing Earth's reflectivity (albedo), tend to:`, ch:[`completely reverse existing warming trends`,`have no effect on the climate system`,`amplify or accelerate further warming`,`slow down further warming`], ans:2, exp:`As reflective ice melts and is replaced by darker land or ocean surfaces, more sunlight is absorbed rather than reflected, which further accelerates warming — a positive feedback loop.` },
      { q:`Which strategy is commonly proposed to help reduce greenhouse gas emissions?`, ch:[`Removing all vegetation from urban areas`,`Increasing the combustion of fossil fuels`,`Increasing the rate of deforestation`,`Transitioning to renewable energy sources, like solar and wind power`], ans:3, exp:`Shifting energy production toward renewable sources that don't rely on burning carbon-based fuels is a major strategy for reducing greenhouse gas emissions.` },
      { q:`Water vapor is technically the most abundant greenhouse gas, but scientists generally treat it as a feedback rather than a primary driver of climate change because:`, ch:[`it actually has no warming effect on the atmosphere`,`it is not actually considered a greenhouse gas`,`it is found only at the poles`,`its atmospheric concentration responds to temperature, rather than steadily accumulating from direct human emissions over time`], ans:3, exp:`Unlike CO2, atmospheric water vapor levels quickly adjust in response to temperature rather than building up over decades from emissions, so it's treated as a feedback that amplifies warming caused by other gases.` },
      { q:`The Paris Agreement is an international effort primarily aimed at:`, ch:[`limiting the rise in global average temperature by reducing greenhouse gas emissions`,`controlling the timing of ocean tides`,`banning all industrial activity worldwide`,`increasing global fossil fuel production`], ans:0, exp:`The Paris Agreement is a landmark international accord in which countries committed to actions aimed at limiting global temperature rise by curbing greenhouse gas emissions.` },
    ]
  },
  {
    id:'cp131', cat:'Physical Sciences', title:'Naming Ionic Compounds', diff:'Easy',
    qs:[
      { q:`Ionic compounds form through the transfer of electrons between:`, ch:[`two metals`,`two noble gases`,`two nonmetals`,`a metal and a nonmetal`], ans:3, exp:`Ionic bonds typically form when a metal loses one or more electrons to a nonmetal, creating oppositely charged ions that attract each other.` },
      { q:`When naming an ionic compound, the cation (metal) name is written:`, ch:[`with an "-ide" ending`,`first, before the anion`,`second, after the anion`,`with a Roman numeral in every case`], ans:1, exp:`Ionic compound names are written with the cation (usually a metal) named first, followed by the anion.` },
      { q:`The anion (nonmetal) portion of a simple ionic compound typically has its ending changed to:`, ch:[`-ous`,`-ic`,`-ide`,`-ate`], ans:2, exp:`Simple monatomic anions are named by changing the element's ending to "-ide," such as chlorine becoming chloride.` },
      { q:`NaCl is correctly named:`, ch:[`sodium(I) chloride`,`disodium chloride`,`sodium chlorine`,`sodium chloride`], ans:3, exp:`NaCl is sodium chloride — the cation name (sodium) stays the same, and the anion (chlorine) becomes chloride.` },
      { q:`MgO is correctly named:`, ch:[`magnesium oxide`,`magnesium dioxide`,`magnesium(II) oxide`,`dimagnesium oxide`], ans:0, exp:`Since magnesium (a main-group metal) has only one common charge (+2), no Roman numeral or prefix is needed: it's simply magnesium oxide.` },
      { q:`For transition metals capable of forming more than one possible charge, such as iron, a Roman numeral is included in the name to indicate:`, ch:[`the charge (oxidation state) of the metal cation`,`the period number of the element`,`the number of atoms in the formula`,`the group number of the element`], ans:0, exp:`Roman numerals specify which charge state a variable-charge metal cation has in that particular compound, since the same metal can form more than one type of ion.` },
      { q:`FeCl2, where iron carries a +2 charge, is correctly named:`, ch:[`iron(III) chloride`,`iron chloride`,`iron(II) chloride`,`diiron chloride`], ans:2, exp:`Because iron can form both +2 and +3 ions, the Roman numeral (II) specifies that this compound contains the +2 iron cation.` },
      { q:`FeCl3, where iron carries a +3 charge, is correctly named:`, ch:[`iron chloride, with no numeral needed`,`triiron chloride`,`iron(III) chloride`,`iron(II) chloride`], ans:2, exp:`The Roman numeral (III) specifies that iron is present as the +3 cation in this compound.` },
      { q:`Polyatomic ions, such as sulfate (SO4^2-) and nitrate (NO3-), are named within ionic compounds by:`, ch:[`using their standard, memorized polyatomic ion names`,`using Roman numerals exclusively`,`ignoring their charge entirely`,`converting them to "-ide" endings, like simple anions`], ans:0, exp:`Polyatomic ions keep their standard names (like sulfate or nitrate) rather than being converted to an "-ide" form, unlike simple monatomic anions.` },
      { q:`Ca(NO3)2 is correctly named:`, ch:[`calcium nitride`,`dicalcium nitrate`,`calcium dinitrate`,`calcium nitrate`], ans:3, exp:`The subscript 2 outside the parentheses balances charge (Ca2+ needs two NO3- ions) but is not stated as a prefix in the name — it's simply calcium nitrate.` },
      { q:`K2SO4 is correctly named:`, ch:[`dipotassium sulfate`,`potassium sulfide`,`potassium sulfate`,`potassium(I) sulfate`], ans:2, exp:`K2SO4 is potassium sulfate; the subscripts needed to balance the +1 potassium ions with the -2 sulfate ion are not stated with prefixes in ionic compound names.` },
      { q:`In naming ionic compounds, subscripts in the chemical formula (such as the "2" in MgCl2) are:`, ch:[`stated explicitly in the name, using prefixes like "di-"`,`only ever used for polyatomic ions`,`not stated in the name, since they are simply determined by charge balance`,`always ignored when writing the formula`], ans:2, exp:`Unlike covalent compound naming, ionic compound names don't use numerical prefixes — the subscripts are inferred from the need to balance the cation and anion charges.` },
      { q:`Al2O3 is correctly named:`, ch:[`aluminum(III) oxide`,`dialuminum trioxide`,`aluminum trioxide`,`aluminum oxide`], ans:3, exp:`Since aluminum has only one common charge (+3), no Roman numeral or prefix is needed — the compound is simply aluminum oxide, with subscripts inferred from charge balance.` },
      { q:`NH4Cl (ammonium chloride) is formed from which combination of ions?`, ch:[`Two monatomic ions`,`A polyatomic cation (ammonium) and a monatomic anion (chloride)`,`Two polyatomic ions`,`Two anions with no cation`], ans:1, exp:`Ammonium (NH4+) is a common polyatomic cation, which here combines with the monatomic chloride anion (Cl-) to form the ionic compound.` },
    ]
  },
  {
    id:'cp132', cat:'Physical Sciences', title:'Naming Covalent Compounds', diff:'Easy',
    qs:[
      { q:`Covalent compounds typically form between:`, ch:[`a metal and a nonmetal`,`a metal and a polyatomic ion`,`two nonmetals`,`two metals`], ans:2, exp:`Covalent bonds form when two nonmetal atoms share electrons, unlike ionic bonds, which form between a metal and a nonmetal.` },
      { q:`In naming binary covalent compounds, numerical prefixes, like mono-, di-, and tri-, are used to indicate:`, ch:[`the number of atoms of each element present in the molecule`,`the charge on each atom`,`the total mass of the compound`,`the type of bond present`], ans:0, exp:`Since the same two nonmetal elements can combine in different ratios to form entirely different compounds, prefixes are used to specify exactly how many atoms of each element are present.` },
      { q:`CO is correctly named:`, ch:[`dicarbon oxide`,`carbon oxide`,`monocarbon oxide`,`carbon monoxide`], ans:3, exp:`CO is carbon monoxide; the prefix "mono-" specifies a single oxygen atom (and is conventionally omitted for the first element when there's only one atom).` },
      { q:`CO2 is correctly named:`, ch:[`carbon(IV) oxide`,`carbon oxide`,`carbon dioxide`,`monocarbon dioxide`], ans:2, exp:`CO2 is carbon dioxide, with "di-" indicating the two oxygen atoms present.` },
      { q:`N2O4 is correctly named:`, ch:[`dinitrogen oxide`,`nitrogen tetraoxide`,`dinitrogen tetroxide`,`nitrogen oxide`], ans:2, exp:`N2O4 is dinitrogen tetroxide, using "di-" for the two nitrogen atoms and "tetr(a)-" for the four oxygen atoms.` },
      { q:`The prefix "mono-" is conventionally omitted for the:`, ch:[`first element listed in the name, when only one atom of it is present`,`second element listed in the name`,`both elements, in all cases`,`neither element, ever`], ans:0, exp:`By convention, "mono-" is dropped for the first element in the name (as in carbon monoxide, not monocarbon monoxide) but is kept for the second element when needed.` },
      { q:`P2O5 is correctly named:`, ch:[`phosphorus(V) oxide`,`pentaphosphorus oxide`,`diphosphorus pentoxide`,`phosphorus oxide`], ans:2, exp:`P2O5 is diphosphorus pentoxide, using "di-" for two phosphorus atoms and "pent(a)-" for five oxygen atoms.` },
      { q:`SF6 is correctly named:`, ch:[`sulfur hexafluoride`,`sulfur(VI) fluoride`,`hexasulfur fluoride`,`sulfur fluoride`], ans:0, exp:`SF6 is sulfur hexafluoride, with "hexa-" indicating the six fluorine atoms bonded to the single sulfur atom.` },
      { q:`Which numerical prefix corresponds to the number 4?`, ch:[`tetra-`,`hexa-`,`tri-`,`penta-`], ans:0, exp:`"Tetra-" indicates four atoms of an element in a covalent compound's name.` },
      { q:`Which numerical prefix corresponds to the number 6?`, ch:[`tetra-`,`hexa-`,`hepta-`,`penta-`], ans:1, exp:`"Hexa-" indicates six atoms of an element in a covalent compound's name.` },
      { q:`Unlike ionic compounds, covalent compound names require numerical prefixes because:`, ch:[`covalent compounds always carry a fixed +1 charge`,`the same two nonmetals can combine in different ratios to form entirely different compounds`,`covalent compounds are always gases`,`covalent compounds never contain more than two atoms`], ans:1, exp:`Since covalent bonding doesn't follow simple charge-balancing rules the way ionic bonding does, prefixes are needed to distinguish compounds like CO and CO2, which have very different properties.` },
      { q:`Water (H2O) is a covalent compound most often known by its common name, but its systematic name would be:`, ch:[`monohydrogen oxide`,`dihydrogen monoxide`,`hydrogen dioxide`,`hydrogen oxide`], ans:1, exp:`Following standard covalent naming rules, H2O would systematically be named dihydrogen monoxide, though "water" is universally used instead in everyday and most scientific contexts.` },
      { q:`N2O is correctly named:`, ch:[`dinitrogen monoxide`,`nitrogen oxide`,`nitrogen dioxide`,`nitrogen monoxide`], ans:0, exp:`N2O is dinitrogen monoxide (also known as nitrous oxide, or "laughing gas"), reflecting its two nitrogen atoms and one oxygen atom.` },
      { q:`The element listed first in a covalent compound's chemical formula and name is generally:`, ch:[`always oxygen`,`the less electronegative element, appearing closer to the metal-like end of the nonmetals`,`always nitrogen`,`the more electronegative element`], ans:1, exp:`By convention, the less electronegative (more metallic-like) nonmetal is written and named first, with the more electronegative element listed second and given the "-ide" ending.` },
    ]
  },
  {
    id:'cp133', cat:'Physical Sciences', title:'Stoichiometry Practice: Mole Ratios', diff:'Medium',
    qs:[
      { q:`In the balanced equation 2H2 + O2 -> 2H2O, what is the mole ratio of H2 to O2?`, ch:[`1:1`,`1:2`,`2:1`,`2:2`], ans:2, exp:`The coefficients directly give the mole ratio: 2 moles of H2 react with 1 mole of O2, a ratio of 2:1.` },
      { q:`Using 2H2 + O2 -> 2H2O, how many moles of H2O form from 4 moles of H2 (with excess O2 available)?`, ch:[`2 moles`,`4 moles`,`1 mole`,`8 moles`], ans:1, exp:`The mole ratio of H2 to H2O is 2:2, or 1:1, so 4 moles of H2 produce 4 moles of H2O.` },
      { q:`Using N2 + 3H2 -> 2NH3, how many moles of NH3 form from 6 moles of H2 (with excess N2 available)?`, ch:[`3 moles`,`2 moles`,`4 moles`,`6 moles`], ans:2, exp:`The mole ratio of H2 to NH3 is 3:2. Using 6 moles of H2: (6 mol H2) x (2 mol NH3 / 3 mol H2) = 4 moles of NH3.` },
      { q:`Using N2 + 3H2 -> 2NH3, how many moles of N2 are needed to react completely with 9 moles of H2?`, ch:[`1 mole`,`3 moles`,`6 moles`,`9 moles`], ans:1, exp:`The mole ratio of N2 to H2 is 1:3. For 9 moles of H2: (9 mol H2) x (1 mol N2 / 3 mol H2) = 3 moles of N2.` },
      { q:`For the combustion reaction CH4 + 2O2 -> CO2 + 2H2O, how many moles of O2 are required to react completely with 2 moles of CH4?`, ch:[`8`,`6`,`4`,`2`], ans:2, exp:`The mole ratio of CH4 to O2 is 1:2, so 2 moles of CH4 require 2 x 2 = 4 moles of O2.` },
      { q:`In a stoichiometry problem, the limiting reactant is the reactant that:`, ch:[`is completely consumed first, limiting the total amount of product that can form`,`has the highest molar mass`,`is present in the greatest quantity`,`does not participate in the reaction at all`], ans:0, exp:`The limiting reactant runs out first, stopping the reaction from producing any more product, regardless of how much of the other reactant remains.` },
      { q:`If you have 3 moles of A and 3 moles of B reacting according to A + 2B -> C, which reactant is limiting?`, ch:[`Neither reactant is limiting`,`A`,`C is limiting`,`B`], ans:3, exp:`Fully reacting 3 moles of A would require 6 moles of B, but only 3 moles of B are available, so B runs out first and is the limiting reactant.` },
      { q:`Using 2Al + 3Cl2 -> 2AlCl3, how many moles of AlCl3 form from 4 moles of Al (with excess Cl2 available)?`, ch:[`8`,`2`,`6`,`4`], ans:3, exp:`The mole ratio of Al to AlCl3 is 2:2, or 1:1, so 4 moles of Al produce 4 moles of AlCl3.` },
      { q:`Percent yield is calculated as:`, ch:[`theoretical yield divided by actual yield, times 100`,`actual yield divided by theoretical yield, times 100`,`theoretical yield multiplied by actual yield`,`actual yield minus theoretical yield`], ans:1, exp:`Percent yield = (actual yield / theoretical yield) x 100%, comparing how much product was actually obtained to the maximum amount predicted.` },
      { q:`If the theoretical yield of a reaction is 20 g and the actual yield obtained in the lab is 15 g, what is the percent yield?`, ch:[`133%`,`25%`,`75%`,`15%`], ans:2, exp:`Percent yield = (15 g / 20 g) x 100% = 75%.` },
      { q:`Given the equation 2KClO3 -> 2KCl + 3O2, how many moles of O2 form from 4 moles of KClO3?`, ch:[`2`,`6`,`3`,`4`], ans:1, exp:`The mole ratio of KClO3 to O2 is 2:3. For 4 moles of KClO3: (4 mol) x (3 mol O2 / 2 mol KClO3) = 6 moles of O2.` },
      { q:`Molar mass is used in stoichiometry calculations primarily to convert between:`, ch:[`moles and volume directly, for any substance`,`liquids and gases only`,`temperature and pressure`,`grams and moles of a substance`], ans:3, exp:`Molar mass (grams per mole) serves as the conversion factor that links a measured mass in grams to the corresponding number of moles.` },
      { q:`In the reaction Fe2O3 + 3CO -> 2Fe + 3CO2, how many moles of Fe form from 2 moles of Fe2O3 (with excess CO available)?`, ch:[`6`,`2`,`4`,`3`], ans:2, exp:`The mole ratio of Fe2O3 to Fe is 1:2, so 2 moles of Fe2O3 produce 2 x 2 = 4 moles of Fe.` },
      { q:`Avogadro's number, approximately 6.022 x 10^23, represents the number of particles contained in:`, ch:[`a single atom`,`one gram of any substance`,`one mole of any substance`,`one liter of any gas, regardless of conditions`], ans:2, exp:`Avogadro's number defines exactly how many particles (atoms, molecules, ions, etc.) make up one mole of any substance.` },
    ]
  },
  {
    id:'cp134', cat:'Physical Sciences', title:'Gas Laws Practice Problems', diff:'Medium',
    qs:[
      { q:`Boyle's Law states that at constant temperature, the pressure and volume of a fixed amount of gas are:`, ch:[`inversely proportional`,`directly proportional`,`completely unrelated`,`always numerically equal`], ans:0, exp:`Boyle's Law (P1V1 = P2V2) shows that as volume decreases, pressure increases proportionally, and vice versa, at constant temperature.` },
      { q:`Using Boyle's Law, if a gas at 2 atm and 4 L is compressed to 2 L at constant temperature, what is the new pressure?`, ch:[`2 atm`,`1 atm`,`8 atm`,`4 atm`], ans:3, exp:`P1V1 = P2V2: (2 atm)(4 L) = P2(2 L), so P2 = 8/2 = 4 atm.` },
      { q:`Charles's Law states that at constant pressure, the volume and temperature (in Kelvin) of a fixed amount of gas are:`, ch:[`directly proportional`,`inversely proportional`,`always numerically equal`,`completely unrelated`], ans:0, exp:`Charles's Law (V1/T1 = V2/T2) shows that volume increases as temperature increases, at constant pressure.` },
      { q:`Using Charles's Law, a gas at 300 K occupies 2 L. If heated to 600 K at constant pressure, what is the new volume?`, ch:[`4 L`,`6 L`,`2 L`,`1 L`], ans:0, exp:`V1/T1 = V2/T2: 2/300 = V2/600, so V2 = (2 x 600)/300 = 4 L.` },
      { q:`Gay-Lussac's Law relates which two quantities at constant volume?`, ch:[`Moles and volume`,`Pressure and temperature`,`Pressure and volume`,`Volume and temperature`], ans:1, exp:`Gay-Lussac's Law states that at constant volume, pressure and temperature (in Kelvin) are directly proportional (P1/T1 = P2/T2).` },
      { q:`Using the combined gas law, P1V1/T1 = P2V2/T2, if P1 = 1 atm, V1 = 10 L, T1 = 273 K, and the gas is compressed to V2 = 5 L while T2 stays at 273 K, what is the new pressure P2?`, ch:[`2 atm`,`4 atm`,`0.5 atm`,`1 atm`], ans:0, exp:`Since T1 = T2, this simplifies to Boyle's Law: (1 atm)(10 L) = P2(5 L), so P2 = 10/5 = 2 atm.` },
      { q:`The ideal gas law is expressed as:`, ch:[`PVT = nR`,`PV = nR/T`,`PV = nRT`,`P/V = nRT`], ans:2, exp:`The ideal gas law, PV = nRT, relates pressure (P), volume (V), number of moles (n), the gas constant (R), and temperature (T) in Kelvin.` },
      { q:`In the ideal gas law equation, R represents:`, ch:[`the temperature in Kelvin`,`the volume of the gas`,`the number of moles of gas`,`the universal gas constant`], ans:3, exp:`R is the universal gas constant (approximately 0.0821 L*atm/(mol*K)), a fixed value used to relate the other variables in the ideal gas law.` },
      { q:`At standard temperature and pressure (STP), one mole of an ideal gas occupies approximately:`, ch:[`11.2 L`,`22.4 L`,`1 L`,`44.8 L`], ans:1, exp:`At STP (0 degrees C and 1 atm), one mole of an ideal gas occupies about 22.4 L, a commonly used reference value in gas law problems.` },
      { q:`If the temperature of a fixed amount of gas at constant volume increases, the pressure of the gas:`, ch:[`decreases`,`stays exactly the same`,`increases`,`drops to zero`], ans:2, exp:`At constant volume, increasing temperature causes gas molecules to move faster and collide with container walls more forcefully and frequently, increasing pressure (Gay-Lussac's Law).` },
      { q:`Using PV = nRT, if you have 2 moles of gas at 1 atm and 273 K (with R = 0.0821 L*atm/(mol*K)), what is the approximate volume?`, ch:[`22.4 L`,`5.6 L`,`44.8 L`,`11.2 L`], ans:2, exp:`V = nRT/P = (2)(0.0821)(273)/1 ≈ 44.8 L, consistent with 2 moles occupying twice the molar volume at STP.` },
      { q:`Avogadro's Law states that at the same temperature and pressure, equal volumes of different gases contain:`, ch:[`the same number of moles (or particles)`,`amounts that vary depending on the identity of the gas`,`no gas particles at all`,`different numbers of moles`], ans:0, exp:`Avogadro's Law states that equal volumes of any ideal gas, under the same temperature and pressure, contain equal numbers of moles, regardless of the gas's identity.` },
      { q:`Dalton's Law of partial pressures states that the total pressure of a gas mixture equals:`, ch:[`the sum of the partial pressures of each individual gas in the mixture`,`only the pressure of the single most abundant gas`,`the average of the individual gas pressures`,`the product of all the partial pressures`], ans:0, exp:`Dalton's Law: Ptotal = P1 + P2 + P3 + ..., where each Pi is the pressure that gas would exert if it alone occupied the container.` },
      { q:`A rigid, sealed container of gas is heated from 200 K to 400 K at constant volume. What happens to the pressure?`, ch:[`It stays exactly the same`,`It doubles`,`It is cut in half`,`It drops to zero`], ans:1, exp:`Since pressure and temperature (in Kelvin) are directly proportional at constant volume, doubling the temperature from 200 K to 400 K doubles the pressure.` },
    ]
  },
  {
    id:'cp135', cat:'Physical Sciences', title:'Functional Groups: An Introduction', diff:'Medium',
    qs:[
      { q:`A functional group is best described as:`, ch:[`the entire carbon skeleton of a molecule`,`a feature found only in inorganic molecules`,`a specific group of atoms within a molecule that is responsible for its characteristic chemical reactions`,`a part of a molecule unrelated to its reactivity`], ans:2, exp:`Functional groups are specific arrangements of atoms (like -OH or -COOH) that give a molecule its characteristic chemical behavior, regardless of the rest of the carbon skeleton.` },
      { q:`An alcohol functional group is characterized by:`, ch:[`a carbon-nitrogen triple bond`,`a carboxyl group`,`a carbon-oxygen double bond`,`a hydroxyl group (-OH) attached to a carbon atom`], ans:3, exp:`Alcohols are defined by a hydroxyl group (-OH) bonded to a carbon atom, as seen in ethanol (CH3CH2OH).` },
      { q:`A carboxylic acid functional group contains:`, ch:[`only a hydroxyl group`,`only a carbonyl group`,`an amine group`,`a carbonyl (C=O) group and a hydroxyl (-OH) group combined together (-COOH)`], ans:3, exp:`Carboxylic acids combine a carbonyl and hydroxyl group into the distinctive -COOH functional group, as found in acetic acid.` },
      { q:`In a ketone functional group, the carbonyl group (C=O) is located:`, ch:[`between two carbon atoms, within the chain`,`attached directly to a nitrogen atom`,`at the very end of a carbon chain`,`attached to two oxygen atoms`], ans:0, exp:`Ketones have their carbonyl group positioned within the carbon chain, bonded to two other carbon atoms on either side.` },
      { q:`In an aldehyde functional group, the carbonyl group is located:`, ch:[`at the end of a carbon chain, attached to at least one hydrogen atom`,`attached to two oxygen atoms`,`only within ring structures`,`only in the middle of a carbon chain`], ans:0, exp:`Aldehydes have their carbonyl group at the terminal end of the carbon chain, bonded to at least one hydrogen atom.` },
      { q:`An amine functional group contains a:`, ch:[`halogen atom`,`carbonyl carbon`,`nitrogen atom bonded to one or more carbon and/or hydrogen atoms`,`sulfur atom`], ans:2, exp:`Amines are characterized by a nitrogen atom bonded to carbon groups and/or hydrogen atoms, similar in structure to ammonia (NH3) with carbons replacing some hydrogens.` },
      { q:`An ester functional group is formed from the reaction of a carboxylic acid with a(n):`, ch:[`alcohol`,`aldehyde`,`ketone`,`amine`], ans:0, exp:`Esters form when a carboxylic acid reacts with an alcohol, releasing water and forming the characteristic ester linkage (-COO-).` },
      { q:`Ethers are characterized by:`, ch:[`a nitrogen atom bonded to two carbon groups`,`an oxygen atom bonded to two separate carbon groups (R-O-R)`,`a carbonyl group`,`a hydroxyl group`], ans:1, exp:`Ethers have an oxygen atom bridging two carbon-containing groups, without the hydroxyl hydrogen found in alcohols.` },
      { q:`Which functional group is present in table sugar (sucrose) and many other carbohydrates?`, ch:[`Hydroxyl (alcohol) groups`,`Halide`,`Amine`,`Thiol`], ans:0, exp:`Carbohydrates like sugars are rich in hydroxyl (-OH) groups, which contribute to their high water solubility.` },
      { q:`A "hydrocarbon" is a molecule composed entirely of:`, ch:[`hydrogen and sulfur`,`carbon and hydrogen only`,`carbon and nitrogen`,`hydrogen and oxygen`], ans:1, exp:`By definition, hydrocarbons contain only carbon and hydrogen atoms, with no other elements present.` },
      { q:`Amides contain a carbonyl group bonded directly to a:`, ch:[`halogen atom`,`hydroxyl group`,`sulfur atom`,`nitrogen atom`], ans:3, exp:`Amides feature a carbonyl carbon bonded to a nitrogen atom, a linkage that is also the basis of the peptide bonds found in proteins.` },
      { q:`Which functional group defines an "alkyl halide"?`, ch:[`A halogen atom (F, Cl, Br, or I) bonded to a carbon`,`A hydroxyl group`,`A nitrogen-containing group`,`A carbonyl group`], ans:0, exp:`Alkyl halides are hydrocarbons in which one or more hydrogen atoms have been replaced by a halogen atom bonded to carbon.` },
      { q:`A thiol functional group is structurally analogous to an alcohol but contains:`, ch:[`oxygen in place of sulfur`,`nitrogen in place of oxygen`,`sulfur in place of oxygen (an -SH group instead of -OH)`,`phosphorus in place of oxygen`], ans:2, exp:`Thiols replace the oxygen of an alcohol's hydroxyl group with sulfur, forming a sulfhydryl (-SH) group instead.` },
      { q:`Identifying the functional groups present in an organic molecule primarily helps predict:`, ch:[`nothing useful about the molecule`,`the molecule's characteristic chemical reactivity and many of its physical properties`,`the molecule's exact mass only`,`the molecule's color exclusively`], ans:1, exp:`Functional groups largely determine how a molecule will react chemically and influence properties like polarity, solubility, and boiling point.` },
    ]
  },
  {
    id:'cp136', cat:'Physical Sciences', title:'Hydrocarbon Naming Basics', diff:'Medium',
    qs:[
      { q:`Alkanes are hydrocarbons characterized by:`, ch:[`a ring of carbons exclusively`,`at least one triple bond`,`only single bonds between carbon atoms (saturated hydrocarbons)`,`only double bonds between carbon atoms`], ans:2, exp:`Alkanes contain only single carbon-carbon and carbon-hydrogen bonds, making them "saturated" with the maximum possible number of hydrogen atoms.` },
      { q:`Alkenes contain at least one:`, ch:[`carbon-carbon triple bond`,`carbon-carbon single bond only`,`carbon-carbon double bond`,`carbon-oxygen bond`], ans:2, exp:`Alkenes are unsaturated hydrocarbons defined by the presence of at least one carbon-carbon double bond.` },
      { q:`Alkynes contain at least one:`, ch:[`carbon-nitrogen bond`,`carbon-carbon triple bond`,`carbon-carbon single bond`,`carbon-carbon double bond`], ans:1, exp:`Alkynes are unsaturated hydrocarbons defined by at least one carbon-carbon triple bond.` },
      { q:`The suffix used when naming an alkane is:`, ch:[`-ol`,`-yne`,`-ene`,`-ane`], ans:3, exp:`Alkane names end in "-ane," such as methane, ethane, and propane.` },
      { q:`The suffix used when naming an alkene is:`, ch:[`-ane`,`-yne`,`-ene`,`-oic acid`], ans:2, exp:`Alkene names end in "-ene," such as ethene and propene.` },
      { q:`The suffix used when naming an alkyne is:`, ch:[`-al`,`-ene`,`-ane`,`-yne`], ans:3, exp:`Alkyne names end in "-yne," such as ethyne and propyne.` },
      { q:`A hydrocarbon with 4 carbon atoms and only single bonds is named:`, ch:[`butene`,`butane`,`propane`,`pentane`], ans:1, exp:`"But-" indicates 4 carbons, and the "-ane" ending confirms only single bonds, giving butane.` },
      { q:`A hydrocarbon with 3 carbon atoms and one double bond is named:`, ch:[`propanol`,`propane`,`propene`,`propyne`], ans:2, exp:`"Prop-" indicates 3 carbons, and the "-ene" ending indicates one double bond, giving propene.` },
      { q:`The general molecular formula for an alkane is:`, ch:[`CnH2n`,`CnHn`,`CnH2n-2`,`CnH2n+2`], ans:3, exp:`Alkanes follow the general formula CnH2n+2, since they are fully saturated with hydrogen atoms.` },
      { q:`The general molecular formula for an alkene with one double bond is:`, ch:[`CnH2n+1`,`CnH2n`,`CnH2n+2`,`CnH2n-2`], ans:1, exp:`Alkenes with a single double bond follow the general formula CnH2n, having two fewer hydrogens than the corresponding alkane.` },
      { q:`Cyclohexane is an example of a:`, ch:[`cyclic (ring-shaped) alkane`,`aromatic compound`,`alkene`,`straight-chain alkane`], ans:0, exp:`Cyclohexane is a six-carbon ring made entirely of single bonds, making it a cyclic alkane rather than a straight-chain one.` },
      { q:`Which prefix indicates 5 carbon atoms in a hydrocarbon's name?`, ch:[`hept-`,`but-`,`hex-`,`pent-`], ans:3, exp:`"Pent-" indicates a five-carbon chain, as in pentane, pentene, or pentyne.` },
      { q:`Isomers are molecules that:`, ch:[`cannot exist among hydrocarbons`,`always have different molecular formulas`,`share the same molecular formula but differ in their structural arrangement`,`have completely identical structures`], ans:2, exp:`Isomers have the same number and type of atoms (same molecular formula) but differ in how those atoms are connected or arranged, giving them different properties.` },
      { q:`Which of the following is a saturated hydrocarbon?`, ch:[`Ethene`,`Ethyne`,`Ethane`,`Benzene`], ans:2, exp:`Ethane, containing only single carbon-carbon and carbon-hydrogen bonds, is a saturated hydrocarbon; the others all contain double, triple, or aromatic (delocalized) bonding.` },
    ]
  },
  {
    id:'cp137', cat:'Physical Sciences', title:'Periodic Table Families & Groups', diff:'Easy',
    qs:[
      { q:`Elements in the same vertical column of the periodic table are called a:`, ch:[`group (family)`,`series`,`block`,`period`], ans:0, exp:`A vertical column on the periodic table is called a group, or family; elements within a group share similar chemical properties.` },
      { q:`Elements in the same horizontal row of the periodic table are called a:`, ch:[`family`,`period`,`isotope set`,`group`], ans:1, exp:`A horizontal row on the periodic table is called a period; elements across a period have the same number of electron shells but differing valence electron counts.` },
      { q:`Group 1 elements, excluding hydrogen, are known as the:`, ch:[`alkaline earth metals`,`noble gases`,`alkali metals`,`halogens`], ans:2, exp:`Group 1 metals (like lithium, sodium, and potassium) are called alkali metals and are known for their high reactivity and single valence electron.` },
      { q:`Group 2 elements are known as the:`, ch:[`halogens`,`alkaline earth metals`,`transition metals`,`alkali metals`], ans:1, exp:`Group 2 elements (like magnesium and calcium) are known as alkaline earth metals, each having two valence electrons.` },
      { q:`Group 17 elements are known as the:`, ch:[`noble gases`,`transition metals`,`halogens`,`alkali metals`], ans:2, exp:`Group 17 elements (like fluorine, chlorine, and bromine) are called halogens, known for their high reactivity and seven valence electrons.` },
      { q:`Group 18 elements are known as the:`, ch:[`transition metals`,`halogens`,`alkaline earth metals`,`noble gases`], ans:3, exp:`Group 18 elements (like helium, neon, and argon) are the noble gases, which have full valence shells and are largely unreactive.` },
      { q:`Elements within the same group of the periodic table generally share similar:`, ch:[`chemical properties, due to having similar valence electron configurations`,`physical color only`,`number of protons`,`exact atomic mass`], ans:0, exp:`Elements in the same group have the same number of valence electrons, which largely determines their similar chemical behavior.` },
      { q:`Alkali metals are characterized by being:`, ch:[`highly reactive, with a single valence electron`,`very unreactive`,`gases at room temperature`,`elements with a completely full outer shell`], ans:0, exp:`With just one loosely held valence electron, alkali metals readily lose that electron, making them among the most reactive metals.` },
      { q:`Noble gases are characterized by having:`, ch:[`a full valence electron shell`,`two valence electrons and high reactivity`,`high chemical reactivity`,`only one valence electron`], ans:0, exp:`Noble gases have a complete valence electron shell, making them exceptionally stable and largely unreactive under normal conditions.` },
      { q:`Halogens are characterized by having:`, ch:[`a full valence shell`,`zero valence electrons`,`metallic properties`,`seven valence electrons and high reactivity`], ans:3, exp:`Halogens have seven valence electrons, just one short of a full shell, which makes them highly reactive as they readily gain an additional electron.` },
      { q:`Transition metals are found in which part of the periodic table?`, ch:[`The middle block of the table, roughly Groups 3 through 12`,`Groups 1 and 2 only`,`Groups 17 and 18 only`,`Only the bottom two rows of the table`], ans:0, exp:`Transition metals occupy the central block of the periodic table, spanning roughly Groups 3 through 12.` },
      { q:`The lanthanides and actinides, often shown as two separate rows below the main table, belong to which period range?`, ch:[`Periods 3 and 4`,`Periods 6 and 7`,`Periods 1 and 2`,`Group 1 only`], ans:1, exp:`The lanthanide series belongs to period 6 and the actinide series to period 7; they are displayed separately purely to keep the table compact.` },
      { q:`Metalloids (semimetals) are elements that:`, ch:[`are always gases at room temperature`,`are found only in Group 1`,`have properties purely characteristic of metals`,`have properties intermediate between metals and nonmetals`], ans:3, exp:`Metalloids, such as silicon and germanium, straddle the boundary between metals and nonmetals on the periodic table and display a mix of both types of properties.` },
      { q:`Which of these elements is a noble gas?`, ch:[`Neon`,`Calcium`,`Chlorine`,`Sodium`], ans:0, exp:`Neon is found in Group 18 and is a noble gas; chlorine is a halogen, sodium is an alkali metal, and calcium is an alkaline earth metal.` },
    ]
  },
  {
    id:'cp138', cat:'Physical Sciences', title:'Atomic Models: History of the Atom', diff:'Easy',
    qs:[
      { q:`John Dalton's early atomic theory proposed that atoms were:`, ch:[`arranged into orbitals of varying probability`,`indivisible, solid spheres`,`mostly empty space`,`made of protons, neutrons, and electrons arranged in shells`], ans:1, exp:`Dalton's early atomic theory (early 1800s) treated atoms as tiny, solid, indivisible spheres, before subatomic particles had been discovered.` },
      { q:`J.J. Thomson's "plum pudding" model proposed that the atom was:`, ch:[`a dense, positively charged nucleus with orbiting electrons`,`a sphere of positive charge with negative electrons embedded throughout it`,`made only of neutrons`,`entirely empty space with no charge`], ans:1, exp:`Thomson's model pictured the atom as a positively charged "pudding" with negatively charged electrons scattered throughout it, like plums.` },
      { q:`Thomson's model was developed shortly after his discovery of the:`, ch:[`electron`,`nucleus`,`proton`,`neutron`], ans:0, exp:`Thomson discovered the electron in 1897 using cathode ray tube experiments, which directly led to his "plum pudding" atomic model.` },
      { q:`Ernest Rutherford's gold foil experiment led him to propose that atoms have:`, ch:[`a uniform distribution of positive charge throughout`,`a small, dense, positively charged nucleus, with electrons occupying mostly empty space around it`,`no nucleus at all`,`only negative charge, with no positive component`], ans:1, exp:`Rutherford's results showed that most of an atom's mass and positive charge is concentrated in a tiny, dense central nucleus, with the rest of the atom being mostly empty space.` },
      { q:`In the gold foil experiment, the fact that most alpha particles passed straight through the foil suggested that:`, ch:[`atoms have no electric charge at all`,`the atom is mostly empty space`,`gold is not actually made of atoms`,`atoms are completely solid throughout`], ans:1, exp:`Since the vast majority of particles passed through undeflected, Rutherford concluded that atoms must be mostly empty space.` },
      { q:`A small fraction of alpha particles in Rutherford's experiment bounced almost straight back. This suggested:`, ch:[`electrons are extremely heavy particles`,`the gold foil used was simply too thick to matter`,`a small, extremely dense, positively charged nucleus exists within the atom`,`atoms are entirely empty, with no dense regions`], ans:2, exp:`Only a concentrated, dense, positively charged nucleus could repel and deflect a small fraction of the incoming alpha particles so dramatically.` },
      { q:`Niels Bohr's model of the atom proposed that electrons:`, ch:[`are spread uniformly throughout the entire atom`,`move in completely random, unpredictable paths at all times`,`do not actually exist around the nucleus`,`orbit the nucleus in fixed, quantized energy levels (shells)`], ans:3, exp:`Bohr's model placed electrons in specific, quantized circular orbits (energy levels) around the nucleus, rather than allowing them to exist at any arbitrary distance.` },
      { q:`According to the Bohr model, an electron emits energy (light) when it:`, ch:[`leaves the atom entirely and becomes a free particle`,`moves to a lower energy level`,`remains in the same energy level`,`moves to a higher energy level`], ans:1, exp:`An electron releases a photon of energy as it falls from a higher to a lower energy level, matching the energy difference between the two levels.` },
      { q:`The modern quantum mechanical model of the atom describes the likely locations of electrons using:`, ch:[`fixed, well-defined circular orbits`,`"plum pudding" style regions`,`solid, uniform spheres`,`probability regions called orbitals`], ans:3, exp:`Unlike Bohr's fixed orbits, the quantum mechanical model describes electron positions in terms of orbitals — three-dimensional regions where an electron is most likely to be found.` },
      { q:`James Chadwick is credited with discovering the:`, ch:[`electron`,`neutron`,`nucleus`,`proton`], ans:1, exp:`Chadwick discovered the neutron in 1932, completing the basic picture of the atom's three primary subatomic particles.` },
      { q:`The discovery of the neutron helped scientists explain:`, ch:[`why atoms carry an overall electric charge`,`why isotopes of the same element can have different atomic masses`,`why atoms were originally thought to be indivisible`,`why electrons carry a negative charge`], ans:1, exp:`Since isotopes of an element have the same number of protons but different numbers of neutrons, the neutron's discovery explained the existence of isotopes with varying atomic masses.` },
      { q:`Among Dalton, Thomson, Rutherford, and Bohr, whose atomic model came chronologically first?`, ch:[`Thomson`,`Bohr`,`Dalton`,`Rutherford`], ans:2, exp:`Dalton's atomic theory, proposed in the early 1800s, predates Thomson's 1897 discovery of the electron and the later models by Rutherford and Bohr.` },
      { q:`Which sequence correctly lists the historical order of atomic models, from earliest to latest?`, ch:[`Thomson, Dalton, Bohr, Rutherford`,`Rutherford, Dalton, Bohr, Thomson`,`Bohr, Thomson, Dalton, Rutherford`,`Dalton, Thomson, Rutherford, Bohr`], ans:3, exp:`The historically correct order is Dalton (solid sphere, ~1803) -> Thomson (plum pudding, 1897) -> Rutherford (nuclear model, 1911) -> Bohr (quantized shells, 1913).` },
      { q:`Robert Millikan's oil drop experiment helped determine the:`, ch:[`charge (and, indirectly, the mass) of the electron`,`mass of the neutron`,`existence of protons`,`size of the atomic nucleus`], ans:0, exp:`Millikan's oil drop experiment precisely measured the electric charge of the electron by balancing gravity against an applied electric field on tiny charged oil droplets.` },
    ]
  },
  {
    id:'cp139', cat:'Physical Sciences', title:'Energy Resources: Renewable vs Nonrenewable', diff:'Easy',
    qs:[
      { q:`Nonrenewable energy resources are those that:`, ch:[`include only solar and wind power`,`replenish quickly on a human timescale`,`are being used up faster than they can naturally re-form, such as fossil fuels`,`never run out, under any circumstances`], ans:2, exp:`Nonrenewable resources, like coal, oil, and natural gas, take millions of years to form, meaning current consumption vastly outpaces their natural replenishment.` },
      { q:`Which of the following is a nonrenewable energy resource?`, ch:[`Solar power`,`Hydropower`,`Wind power`,`Coal`], ans:3, exp:`Coal is a fossil fuel formed over millions of years from ancient organic material, making it a nonrenewable resource, unlike solar, wind, and hydropower.` },
      { q:`Which of the following is a renewable energy resource?`, ch:[`Petroleum (oil)`,`Natural gas`,`Coal`,`Wind power`], ans:3, exp:`Wind power harnesses a naturally replenishing resource (moving air), making it renewable, unlike fossil fuels such as natural gas, oil, and coal.` },
      { q:`Fossil fuels, such as coal, oil, and natural gas, formed from:`, ch:[`recently living organisms`,`volcanic rock`,`ocean salt deposits`,`the remains of ancient organisms compressed and transformed over millions of years`], ans:3, exp:`Fossil fuels form from the remains of ancient plants and organisms that were buried, compressed, and chemically transformed over vast spans of geologic time.` },
      { q:`Burning fossil fuels releases which gas as a major byproduct, contributing to the greenhouse effect?`, ch:[`Carbon dioxide`,`Helium`,`Nitrogen`,`Oxygen`], ans:0, exp:`Combustion of carbon-based fossil fuels releases carbon dioxide, a major greenhouse gas linked to global warming.` },
      { q:`Nuclear power plants generate electricity primarily through:`, ch:[`nuclear fission reactions, which release heat used to produce steam and turn turbines`,`burning uranium like an ordinary fossil fuel`,`large-scale wind turbines`,`solar panels installed on the plant's roof`], ans:0, exp:`Nuclear power plants split heavy atomic nuclei (fission), releasing heat that boils water into steam, which then drives turbines to generate electricity.` },
      { q:`Solar energy is generally captured using:`, ch:[`wind turbines`,`nuclear reactors`,`hydroelectric dams`,`photovoltaic cells or solar thermal collectors`], ans:3, exp:`Solar energy is harvested either by photovoltaic cells, which directly convert sunlight into electricity, or by solar thermal collectors, which use sunlight to heat a fluid.` },
      { q:`Hydroelectric power generates electricity by:`, ch:[`splitting water molecules through nuclear fission`,`burning water as a fuel`,`using the flow or falling motion of water to turn turbines`,`using solar panels to heat water`], ans:2, exp:`Hydroelectric dams use the kinetic energy of flowing or falling water to spin turbines connected to electricity generators.` },
      { q:`Wind power converts the kinetic energy of moving air into electricity using:`, ch:[`hydroelectric dams`,`nuclear reactors`,`wind turbines`,`solar panels`], ans:2, exp:`Wind turbines use large blades that spin as wind passes over them, driving a generator that converts that mechanical energy into electricity.` },
      { q:`Geothermal energy harnesses heat that originates from:`, ch:[`the combustion of coal`,`the Sun`,`Earth's interior`,`ocean wave motion`], ans:2, exp:`Geothermal energy taps into naturally occurring heat from deep within Earth, often accessed through hot springs, geysers, or drilled wells.` },
      { q:`A major environmental advantage of renewable energy sources compared to fossil fuels is that renewables:`, ch:[`produce significantly more greenhouse gases`,`generally produce little to no direct greenhouse gas emissions during operation`,`are always cheaper to build in every situation`,`never require the use of any land`], ans:1, exp:`Most renewable energy technologies, once built, produce electricity without directly emitting greenhouse gases, unlike the combustion of fossil fuels.` },
      { q:`Biomass energy is derived from:`, ch:[`the rise and fall of ocean tides`,`organic materials, such as plants and waste, that can be burned or converted into fuel`,`nuclear fission or fusion reactions`,`wind currents in the atmosphere`], ans:1, exp:`Biomass energy comes from burning or converting organic matter (like wood, crop waste, or biofuels) into usable energy.` },
      { q:`One notable challenge of solar and wind energy is that:`, ch:[`they can only be used in a small handful of specific countries`,`they are technically nonrenewable resources`,`their energy production is intermittent, depending on weather conditions and time of day`,`they produce excessive amounts of pollution`], ans:2, exp:`Solar and wind power output varies depending on weather, time of day, and season, requiring energy storage or backup sources to ensure a steady supply.` },
      { q:`Which statement best describes a key difference between renewable and nonrenewable resources?`, ch:[`Nonrenewables always burn more cleanly than renewables`,`There is no meaningful difference between the two categories`,`Renewables naturally replenish on a human timescale, while nonrenewables take millions of years to form or exist only in finite quantities`,`Renewables are always more expensive to develop, with no exceptions`], ans:2, exp:`The defining distinction is the rate of natural replenishment: renewable resources regenerate within a human lifetime, while nonrenewable resources form far too slowly to keep pace with consumption.` },
    ]
  },
  {
    id:'cp140', cat:'Physical Sciences', title:'Nuclear Chemistry Basics: Fission, Fusion & Radiation Types', diff:'Medium',
    qs:[
      { q:`Nuclear fission is the process of:`, ch:[`releasing electrons from an atom's outer shell`,`converting mass entirely into visible light`,`splitting a heavy nucleus into two or more lighter nuclei`,`combining two light nuclei into a single, heavier nucleus`], ans:2, exp:`Fission occurs when a heavy atomic nucleus (like uranium-235) splits into smaller nuclei, releasing a large amount of energy in the process.` },
      { q:`Nuclear fusion is the process of:`, ch:[`combining two light nuclei, such as hydrogen isotopes, into a single heavier nucleus`,`splitting a heavy nucleus into smaller pieces`,`releasing alpha particles exclusively`,`absorbing a neutron without any resulting change`], ans:0, exp:`Fusion combines light nuclei, such as isotopes of hydrogen, into a heavier nucleus (like helium), releasing enormous amounts of energy in the process.` },
      { q:`The energy source of the Sun and most other stars is primarily:`, ch:[`radioactive decay alone`,`nuclear fission`,`nuclear fusion of hydrogen into helium`,`ordinary chemical combustion`], ans:2, exp:`Stars generate their energy mainly through the fusion of hydrogen nuclei into helium within their extremely hot, dense cores.` },
      { q:`Nuclear power plants operating on Earth today generate electricity primarily using:`, ch:[`chemical combustion of uranium`,`nuclear fission of uranium or plutonium`,`nuclear fusion reactors`,`solar-powered fusion devices`], ans:1, exp:`Current commercial nuclear power plants rely on controlled fission of uranium (or sometimes plutonium) to generate heat for electricity production; practical fusion power plants do not yet exist commercially.` },
      { q:`An alpha particle consists of:`, ch:[`two protons and two neutrons, equivalent to a helium nucleus`,`a single neutron`,`a high-energy photon`,`a single electron`], ans:0, exp:`An alpha particle is identical to a helium-4 nucleus, containing two protons and two neutrons.` },
      { q:`A beta particle is essentially:`, ch:[`a photon of light`,`a free neutron`,`a high-speed electron (or, less commonly, a positron) emitted from a decaying nucleus`,`a helium nucleus`], ans:2, exp:`Beta decay releases a fast-moving electron (beta-minus) or positron (beta-plus) as a neutron converts to a proton (or vice versa) within the nucleus.` },
      { q:`Gamma radiation consists of:`, ch:[`fast-moving electrons`,`helium nuclei`,`slow-moving neutrons`,`high-energy electromagnetic radiation (photons), with no mass or charge`], ans:3, exp:`Gamma rays are high-energy photons, a form of electromagnetic radiation, carrying no mass or electric charge.` },
      { q:`Among alpha, beta, and gamma radiation, which has the greatest penetrating power?`, ch:[`Alpha`,`They all penetrate equally`,`Gamma`,`Beta`], ans:2, exp:`Gamma rays penetrate matter far more deeply than alpha or beta particles and require thick shielding, such as lead or concrete, to significantly reduce their intensity.` },
      { q:`Among alpha, beta, and gamma radiation, which can be stopped by a simple sheet of paper?`, ch:[`None of them`,`Gamma`,`Alpha`,`Beta`], ans:2, exp:`Alpha particles are relatively large and heavily charged, so they have very low penetrating power and can be stopped by something as thin as a sheet of paper.` },
      { q:`Which type of radiation is typically stopped by a few millimeters of aluminum but easily passes through paper?`, ch:[`Gamma`,`Neutron radiation only`,`Beta`,`Alpha`], ans:2, exp:`Beta particles penetrate farther than alpha particles (passing through paper) but are stopped by a thin layer of a denser material, such as aluminum.` },
      { q:`A chain reaction in nuclear fission occurs when:`, ch:[`a single neutron is absorbed and no further reaction takes place`,`neutrons released from one fission event go on to trigger further fission events in nearby nuclei`,`additional energy input halts the reaction`,`protons are continuously released with no further effect`], ans:1, exp:`Each fission event releases multiple neutrons, which can strike other fissile nuclei and trigger further fission events, sustaining a self-propagating chain reaction.` },
      { q:`Control rods in a nuclear fission reactor function by:`, ch:[`absorbing excess neutrons to regulate or slow down the chain reaction`,`speeding up the chain reaction`,`cooling the reactor using water alone`,`adding additional nuclear fuel to the reactor`], ans:0, exp:`Control rods are made of materials that readily absorb neutrons, allowing operators to slow, speed up, or stop the fission chain reaction as needed.` },
      { q:`A key challenge that has so far prevented practical, large-scale nuclear fusion power on Earth is:`, ch:[`achieving and sustaining the extremely high temperatures and pressures needed for fusion in a controlled, economical way`,`fusion produces far too little energy to ever be useful`,`there is no hydrogen available on Earth to use as fuel`,`fusion reactions are not actually exothermic`], ans:0, exp:`Fusion requires extraordinarily high temperatures and pressures to overcome the natural repulsion between positively charged nuclei, which has proven extremely difficult and costly to sustain and contain.` },
      { q:`Compared to nuclear fission, nuclear fusion generally:`, ch:[`releases more energy per unit mass of fuel and produces less long-lived radioactive waste`,`cannot release any usable energy at all`,`only occurs at very low temperatures`,`produces more long-lived radioactive waste`], ans:0, exp:`Fusion reactions release more energy per unit mass of fuel than fission and produce comparatively little long-lived radioactive waste, which is part of what makes fusion an appealing long-term energy goal.` },
    ]
  },
];
